#![cfg_attr(not(feature = "std"), no_std)]
#![deny(unsafe_code)]

#[cfg(not(feature = "std"))]
extern crate alloc;

#[cfg(not(feature = "std"))]
use alloc::{format, vec, vec::Vec};
#[cfg(feature = "std")]
use std::{format, vec, vec::Vec};

/// An RGBA pixel image, 4 bytes per pixel.
///
/// Row-major, top-to-bottom. Alpha is always 255 for DjVu pages.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Pixmap {
    pub width: u32,
    pub height: u32,
    /// RGBA pixel data, row-major. Length = width * height * 4.
    pub data: Vec<u8>,
}

impl AsRef<[u8]> for Pixmap {
    fn as_ref(&self) -> &[u8] {
        &self.data
    }
}

impl Pixmap {
    /// Maximum pixels per pixmap (~64 megapixels = ~256 MB RGBA).
    /// Anything beyond this is a runaway DPI — return an empty pixmap
    /// so the caller gets a harmless blank instead of OOM or overflow.
    const MAX_PIXELS: usize = 64 * 1024 * 1024;

    /// Create a new pixmap filled with the given RGBA color.
    ///
    /// Returns an empty 0×0 pixmap if `width * height` would exceed
    /// 64 MiB pixels or overflow `usize`, preventing OOM from extreme
    /// DPI values.
    pub fn new(width: u32, height: u32, r: u8, g: u8, b: u8, a: u8) -> Self {
        let Some(pixel_count) = (width as usize).checked_mul(height as usize) else {
            return Self::default();
        };
        if pixel_count > Self::MAX_PIXELS {
            return Self::default();
        }
        // Fast path: all channels equal — single memset.
        if r == g && g == b && b == a {
            return Pixmap {
                width,
                height,
                data: vec![r; pixel_count * 4],
            };
        }
        // General path: repeat the 4-byte RGBA pattern `pixel_count` times.
        // `slice::repeat` uses a doubling memcpy strategy and is highly optimised.
        let data = [r, g, b, a].repeat(pixel_count);
        Pixmap {
            width,
            height,
            data,
        }
    }

    /// Create a white opaque pixmap.
    pub fn white(width: u32, height: u32) -> Self {
        Self::new(width, height, 255, 255, 255, 255)
    }

    /// Set pixel at (x, y) to an RGB value (alpha = 255).
    /// Silently ignores out-of-bounds writes (e.g. on an empty overflow pixmap).
    #[inline]
    pub fn set_rgb(&mut self, x: u32, y: u32, r: u8, g: u8, b: u8) {
        let idx = (y as usize * self.width as usize + x as usize) * 4;
        if let Some(pixel) = self.data.get_mut(idx..idx + 4) {
            pixel[0] = r;
            pixel[1] = g;
            pixel[2] = b;
            pixel[3] = 255;
        }
    }

    /// Get the 4 RGBA bytes at pixel (x, y), or `None` if out of bounds.
    #[inline]
    pub fn get_pixel(&self, x: u32, y: u32) -> Option<&[u8]> {
        if x >= self.width || y >= self.height {
            return None;
        }
        let idx = (y as usize * self.width as usize + x as usize) * 4;
        self.data.get(idx..idx + 4)
    }

    /// Get RGB at (x, y). Returns (0, 0, 0) for out-of-bounds reads.
    #[inline]
    pub fn get_rgb(&self, x: u32, y: u32) -> (u8, u8, u8) {
        let idx = (y as usize * self.width as usize + x as usize) * 4;
        if let Some(pixel) = self.data.get(idx..idx + 4) {
            (pixel[0], pixel[1], pixel[2])
        } else {
            (0, 0, 0)
        }
    }

    /// Extract RGB pixel data (3 bytes per pixel), discarding alpha.
    pub fn to_rgb(&self) -> Vec<u8> {
        let pixel_count = self.data.len() / 4;
        let mut out = Vec::with_capacity(pixel_count * 3);
        for chunk in self.data.chunks_exact(4) {
            out.push(chunk[0]);
            out.push(chunk[1]);
            out.push(chunk[2]);
        }
        out
    }

    /// Encode as PPM (binary, P6 format).
    /// This is the format produced by `ddjvu -format=ppm`.
    /// Discards alpha channel.
    pub fn to_ppm(&self) -> Vec<u8> {
        let header = format!("P6\n{} {}\n255\n", self.width, self.height);
        let pixel_count = self.data.len() / 4;
        let mut out = Vec::with_capacity(header.len() + pixel_count * 3);
        out.extend_from_slice(header.as_bytes());
        for chunk in self.data.chunks_exact(4) {
            out.push(chunk[0]); // R
            out.push(chunk[1]); // G
            out.push(chunk[2]); // B
        }
        out
    }

    /// Rotate this pixmap 90° clockwise.
    pub fn rotate_cw90(&self) -> Self {
        let (w, h) = (self.width, self.height);
        let mut dst = vec![0u8; (w * h * 4) as usize];
        for y in 0..h {
            for x in 0..w {
                let src_off = ((y * w + x) * 4) as usize;
                let dst_x = h - 1 - y;
                let dst_y = x;
                let dst_off = ((dst_y * h + dst_x) * 4) as usize;
                dst[dst_off..dst_off + 4].copy_from_slice(&self.data[src_off..src_off + 4]);
            }
        }
        Pixmap {
            width: h,
            height: w,
            data: dst,
        }
    }

    /// Rotate this pixmap 180°.
    pub fn rotate_180(&self) -> Self {
        let (w, h) = (self.width, self.height);
        let mut dst = vec![0u8; (w * h * 4) as usize];
        for y in 0..h {
            for x in 0..w {
                let src_off = ((y * w + x) * 4) as usize;
                let dst_off = (((h - 1 - y) * w + (w - 1 - x)) * 4) as usize;
                dst[dst_off..dst_off + 4].copy_from_slice(&self.data[src_off..src_off + 4]);
            }
        }
        Pixmap {
            width: w,
            height: h,
            data: dst,
        }
    }

    /// Rotate this pixmap 90° counter-clockwise.
    pub fn rotate_ccw90(&self) -> Self {
        let (w, h) = (self.width, self.height);
        let mut dst = vec![0u8; (w * h * 4) as usize];
        for y in 0..h {
            for x in 0..w {
                let src_off = ((y * w + x) * 4) as usize;
                let dst_x = y;
                let dst_y = w - 1 - x;
                let dst_off = ((dst_y * h + dst_x) * 4) as usize;
                dst[dst_off..dst_off + 4].copy_from_slice(&self.data[src_off..src_off + 4]);
            }
        }
        Pixmap {
            width: h,
            height: w,
            data: dst,
        }
    }

    /// Convert to 8-bit grayscale using ITU-R BT.601 luminance weights.
    ///
    /// `Y = 0.299·R + 0.587·G + 0.114·B`
    ///
    /// Returns a [`GrayPixmap`] with `data.len() == width * height`.
    pub fn to_gray8(&self) -> GrayPixmap {
        let pixel_count = self.data.len() / 4;
        let mut data = Vec::with_capacity(pixel_count);
        for chunk in self.data.chunks_exact(4) {
            let r = chunk[0] as u32;
            let g = chunk[1] as u32;
            let b = chunk[2] as u32;
            // Fixed-point: weights × 1024 → 306 + 601 + 117 = 1024
            let y = (r * 306 + g * 601 + b * 117) >> 10;
            data.push(y.min(255) as u8);
        }
        GrayPixmap {
            width: self.width,
            height: self.height,
            data,
        }
    }
}

/// An 8-bit grayscale image, 1 byte per pixel.
///
/// Row-major, top-to-bottom. `data.len() == width * height`.
/// Produced by [`Pixmap::to_gray8`] or [`crate::djvu_render::render_gray8`].
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct GrayPixmap {
    pub width: u32,
    pub height: u32,
    /// Grayscale pixel data, row-major. Length = `width * height`.
    pub data: Vec<u8>,
}

impl GrayPixmap {
    /// Get the luminance value at pixel (x, y).
    #[inline]
    pub fn get(&self, x: u32, y: u32) -> u8 {
        self.data[(y as usize * self.width as usize) + x as usize]
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn white_pixmap() {
        let pm = Pixmap::white(2, 2);
        assert_eq!(pm.data.len(), 16);
        for chunk in pm.data.chunks(4) {
            assert_eq!(chunk, &[255, 255, 255, 255]);
        }
    }

    #[test]
    fn set_get_rgb() {
        let mut pm = Pixmap::white(3, 3);
        pm.set_rgb(1, 1, 100, 150, 200);
        assert_eq!(pm.get_rgb(1, 1), (100, 150, 200));
        assert_eq!(pm.get_rgb(0, 0), (255, 255, 255));
    }

    #[test]
    fn rotate_cw90_swaps_dimensions() {
        let pm = Pixmap::white(4, 2);
        let r = pm.rotate_cw90();
        assert_eq!((r.width, r.height), (2, 4));
    }

    #[test]
    fn rotate_180_preserves_dimensions() {
        let pm = Pixmap::white(4, 2);
        let r = pm.rotate_180();
        assert_eq!((r.width, r.height), (4, 2));
    }

    #[test]
    fn rotate_ccw90_swaps_dimensions() {
        let pm = Pixmap::white(4, 2);
        let r = pm.rotate_ccw90();
        assert_eq!((r.width, r.height), (2, 4));
    }

    #[test]
    fn rotate_cw90_then_ccw90_is_identity() {
        let mut pm = Pixmap::white(3, 2);
        pm.set_rgb(0, 0, 255, 0, 0); // red top-left
        pm.set_rgb(2, 1, 0, 0, 255); // blue bottom-right
        let roundtrip = pm.rotate_cw90().rotate_ccw90();
        assert_eq!(roundtrip.data, pm.data);
        assert_eq!((roundtrip.width, roundtrip.height), (pm.width, pm.height));
    }

    #[test]
    fn rotate_180_twice_is_identity() {
        let mut pm = Pixmap::white(3, 2);
        pm.set_rgb(1, 0, 10, 20, 30);
        let roundtrip = pm.rotate_180().rotate_180();
        assert_eq!(roundtrip.data, pm.data);
    }

    #[test]
    fn rotate_cw90_moves_top_left_to_top_right() {
        // 2×1 pixmap: red pixel at (0,0), white at (1,0)
        let mut pm = Pixmap::white(2, 1);
        pm.set_rgb(0, 0, 255, 0, 0);
        // After CW90: 1×2, red should be at (0,0) in new coords
        // new_x = h-1-y = 1-1-0=0, new_y = x = 0 → (0,0)
        let r = pm.rotate_cw90();
        assert_eq!(r.width, 1);
        assert_eq!(r.height, 2);
        assert_eq!(r.get_rgb(0, 0), (255, 0, 0));
        assert_eq!(r.get_rgb(0, 1), (255, 255, 255));
    }

    #[test]
    fn to_ppm_format() {
        let mut pm = Pixmap::white(2, 1);
        pm.set_rgb(0, 0, 255, 0, 0); // red
        pm.set_rgb(1, 0, 0, 0, 255); // blue
        let ppm = pm.to_ppm();
        let header = b"P6\n2 1\n255\n";
        assert_eq!(&ppm[..header.len()], header);
        assert_eq!(&ppm[header.len()..], &[255, 0, 0, 0, 0, 255]);
    }
}

//! ZP adaptive binary arithmetic encoder.
//!
//! Encoding counterpart to [`super::ZpDecoder`]. Produces byte streams
//! that the decoder can consume. Matches DjVuLibre's ZPCodec encoder.

use super::tables::{LPS_NEXT, MPS_NEXT, PROB, THRESHOLD};

/// ZP adaptive binary arithmetic encoder.
///
/// All internal registers (`a`, `subend`) are `u32` to match DjVuLibre's
/// `unsigned int` types. They hold u16-range values but intermediate
/// arithmetic can exceed 0xFFFF, which is critical for correct carry
/// propagation in `zemit`.
pub struct ZpEncoder {
    /// Current interval width — stored as u32 but logically u16 after shifts.
    a: u32,
    /// Sub-interval lower bound for bit emission — u32 for carry propagation.
    subend: u32,
    /// 24-bit shift buffer for carry propagation (initialized to 0xFFFFFF).
    buffer: u32,
    /// Pending zero-byte run count for carry propagation.
    nrun: i32,
    /// Delay counter: first 25 outbit calls are absorbed.
    delay: i32,
    /// Byte accumulator for output.
    byte: u8,
    /// Bits accumulated in `byte` (0..8).
    scount: u32,
    /// Output bytes.
    output: Vec<u8>,
}

impl Default for ZpEncoder {
    fn default() -> Self {
        Self::new()
    }
}

impl ZpEncoder {
    pub fn new() -> Self {
        Self {
            a: 0,
            subend: 0,
            buffer: 0xffffff,
            nrun: 0,
            delay: 25,
            byte: 0,
            scount: 0,
            output: Vec::new(),
        }
    }

    /// Encode one bit using an adaptive probability context.
    ///
    /// Matches DjVuLibre's inline `encoder(int bit, BitContext &ctx)`:
    /// - LPS always calls encode_lps
    /// - MPS with z >= 0x8000 calls encode_mps
    /// - MPS with z < 0x8000 takes fast path (a = z, no shift)
    pub fn encode_bit(&mut self, ctx: &mut u8, bit: bool) {
        let state = *ctx as usize;
        let mps_bit = (state & 1) != 0;
        let z = self.a + PROB[state] as u32;

        if bit != mps_bit {
            self.encode_lps(ctx, z);
        } else if z >= 0x8000 {
            self.encode_mps(ctx, z);
        } else {
            // Fast path: MPS and z < 0x8000 — just update a, no shift
            self.a = z;
        }
    }

    /// Encode one bit in IW44 passthrough mode (threshold `z = 0x8000 + 3a/8`).
    ///
    /// Counterpart to [`ZpDecoder::decode_passthrough_iw44`]; must produce a
    /// stream that it correctly decodes.
    pub fn encode_passthrough_iw44(&mut self, bit: bool) {
        let z = 0x8000 + (3 * self.a / 8);
        // Invariant: self.a < 0x8000 (all encode paths maintain this).
        // Therefore z = 0x8000 + 3a/8 ∈ [0x8000, 0xB000) — always ≥ 0x8000.
        if !bit {
            self.a = z;
            // z ≥ 0x8000 always — single unconditional shift
            self.zemit(1 - (self.subend >> 15) as i32);
            self.subend = (self.subend << 1) & 0xffff;
            self.a = (self.a << 1) & 0xffff;
        } else {
            let z_comp = 0x10000 - z;
            self.subend += z_comp;
            self.a += z_comp;
            while self.a >= 0x8000 {
                self.zemit(1 - (self.subend >> 15) as i32);
                self.subend = (self.subend << 1) & 0xffff;
                self.a = (self.a << 1) & 0xffff;
            }
        }
    }

    pub fn encode_passthrough(&mut self, bit: bool) {
        let z = 0x8000 + (self.a >> 1);
        // Invariant: self.a < 0x8000, so z = 0x8000 + a/2 ∈ [0x8000, 0xC000) — always ≥ 0x8000.
        if !bit {
            // false (MPS-like): a = z, single unconditional shift
            self.a = z;
            self.zemit(1 - (self.subend >> 15) as i32);
            self.subend = (self.subend << 1) & 0xffff;
            self.a = (self.a << 1) & 0xffff;
        } else {
            // true (LPS-like): z_comp = 0x10000 - z
            let z_comp = 0x10000 - z;
            self.subend += z_comp;
            self.a += z_comp;
            while self.a >= 0x8000 {
                self.zemit(1 - (self.subend >> 15) as i32);
                self.subend = (self.subend << 1) & 0xffff;
                self.a = (self.a << 1) & 0xffff;
            }
        }
    }

    /// Flush the encoder and return the compressed byte stream.
    pub fn finish(mut self) -> Vec<u8> {
        // eflush: round subend up to disambiguate
        if self.subend > 0x8000 {
            self.subend = 0x10000;
        } else if self.subend > 0 {
            self.subend = 0x8000;
        }
        // Emit until buffer is flushed and subend is 0
        while self.buffer != 0xffffff || self.subend != 0 {
            self.zemit(1 - (self.subend >> 15) as i32);
            self.subend = (self.subend << 1) & 0xffff;
        }
        // Final bits
        self.outbit(1);
        while self.nrun > 0 {
            self.nrun -= 1;
            self.outbit(0);
        }
        // Pad remaining byte with 1s
        while self.scount > 0 {
            self.outbit(1);
        }
        self.delay = 0xff; // prevent further output
        // Ensure minimum 2 bytes for decoder initialization
        while self.output.len() < 2 {
            self.output.push(0xff);
        }
        self.output
    }

    fn encode_mps(&mut self, ctx: &mut u8, z: u32) {
        // Clamp z: d = 0x6000 + (z + a) / 4
        let d = 0x6000 + ((z + self.a) >> 2);
        let z = z.min(d);

        if (self.a & 0xffff) as u16 >= THRESHOLD[*ctx as usize] {
            *ctx = MPS_NEXT[*ctx as usize];
        }
        // Code MPS bit + single shift
        self.a = z;
        self.zemit(1 - (self.subend >> 15) as i32);
        self.subend = (self.subend << 1) & 0xffff;
        self.a = (self.a << 1) & 0xffff;
    }

    fn encode_lps(&mut self, ctx: &mut u8, z: u32) {
        // Clamp z
        let d = 0x6000 + ((z + self.a) >> 2);
        let z = z.min(d);

        *ctx = LPS_NEXT[*ctx as usize];
        let z_comp = 0x10000 - z;
        self.subend += z_comp;
        self.a += z_comp;
        while self.a >= 0x8000 {
            self.zemit(1 - (self.subend >> 15) as i32);
            self.subend = (self.subend << 1) & 0xffff;
            self.a = (self.a << 1) & 0xffff;
        }
    }

    /// Emit one bit through the 24-bit carry-propagation buffer.
    fn zemit(&mut self, b: i32) {
        self.buffer = (self.buffer << 1).wrapping_add(b as u32);
        let top = self.buffer >> 24;
        self.buffer &= 0xffffff;
        match top {
            1 => {
                self.outbit(1);
                while self.nrun > 0 {
                    self.nrun -= 1;
                    self.outbit(0);
                }
            }
            0xff => {
                self.outbit(0);
                while self.nrun > 0 {
                    self.nrun -= 1;
                    self.outbit(1);
                }
            }
            0 => {
                self.nrun += 1;
            }
            _ => {} // shouldn't happen
        }
    }

    /// Emit one bit to the output byte stream (with delay).
    fn outbit(&mut self, bit: i32) {
        if self.delay > 0 {
            if self.delay < 0xff {
                self.delay -= 1;
            }
            return;
        }
        self.byte = (self.byte << 1) | (bit as u8);
        self.scount += 1;
        if self.scount == 8 {
            self.output.push(self.byte);
            self.scount = 0;
            self.byte = 0;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ZpDecoder;

    #[test]
    fn zp_roundtrip_passthrough_false() {
        let mut enc = ZpEncoder::new();
        for _ in 0..100 {
            enc.encode_passthrough(false);
        }
        let compressed = enc.finish();
        assert!(!compressed.is_empty());

        let mut dec = ZpDecoder::new(&compressed).expect("init");
        for i in 0..100 {
            let got = dec.decode_passthrough();
            assert!(!got, "expected false at bit {i}");
        }
    }

    #[test]
    fn zp_roundtrip_passthrough_true() {
        let mut enc = ZpEncoder::new();
        for _ in 0..100 {
            enc.encode_passthrough(true);
        }
        let compressed = enc.finish();
        assert!(!compressed.is_empty());

        let mut dec = ZpDecoder::new(&compressed).expect("init");
        for i in 0..100 {
            let got = dec.decode_passthrough();
            assert!(got, "expected true at bit {i}");
        }
    }

    #[test]
    fn zp_roundtrip_context_all_mps() {
        let n = 200;
        let mut enc = ZpEncoder::new();
        let mut ctx = 0u8;
        for _ in 0..n {
            enc.encode_bit(&mut ctx, false);
        }
        let compressed = enc.finish();
        let mut dec = ZpDecoder::new(&compressed).expect("init");
        let mut dec_ctx = 0u8;
        for i in 0..n {
            let got = dec.decode_bit(&mut dec_ctx);
            assert!(!got, "all-MPS mismatch at bit {i}");
        }
    }

    #[test]
    fn zp_roundtrip_context_all_lps() {
        let n = 200;
        let mut enc = ZpEncoder::new();
        let mut ctx = 0u8;
        for _ in 0..n {
            enc.encode_bit(&mut ctx, true);
        }
        let compressed = enc.finish();
        let mut dec = ZpDecoder::new(&compressed).expect("init");
        let mut dec_ctx = 0u8;
        for i in 0..n {
            let got = dec.decode_bit(&mut dec_ctx);
            assert!(got, "all-LPS mismatch at bit {i}");
        }
    }

    #[test]
    fn zp_roundtrip_context_bits() {
        let mut rng: u64 = 0xdead_beef;
        let n = 2000;
        let mut bits = Vec::with_capacity(n);
        let mut enc = ZpEncoder::new();
        let mut ctx = 0u8;
        for _ in 0..n {
            rng ^= rng << 13;
            rng ^= rng >> 7;
            rng ^= rng << 17;
            let bit = (rng & 1) != 0;
            bits.push(bit);
            enc.encode_bit(&mut ctx, bit);
        }
        let compressed = enc.finish();
        let mut dec = ZpDecoder::new(&compressed).expect("init");
        let mut dec_ctx = 0u8;
        for (i, &expected) in bits.iter().enumerate() {
            let got = dec.decode_bit(&mut dec_ctx);
            assert_eq!(got, expected, "mismatch at bit {i}");
        }
    }

    #[test]
    fn zp_roundtrip_mixed() {
        let mut enc = ZpEncoder::new();
        let mut ctx = [0u8; 2];
        let mut seq: Vec<(bool, bool)> = Vec::new();

        for i in 0..500 {
            let is_pt = i % 5 == 0;
            let bit = (i * 13 + 7) % 3 != 0;
            seq.push((is_pt, bit));
            if is_pt {
                enc.encode_passthrough(bit);
            } else {
                enc.encode_bit(&mut ctx[i % 2], bit);
            }
        }
        let compressed = enc.finish();

        let mut dec = ZpDecoder::new(&compressed).expect("init");
        let mut dec_ctx = [0u8; 2];
        for (i, &(is_pt, expected)) in seq.iter().enumerate() {
            let got = if is_pt {
                dec.decode_passthrough()
            } else {
                dec.decode_bit(&mut dec_ctx[i % 2])
            };
            assert_eq!(got, expected, "mismatch at step {i} (pt={is_pt})");
        }
    }

    #[test]
    fn zp_roundtrip_multiple_contexts() {
        let mut rng: u64 = 42;
        let n = 1000;
        let nctx = 4;
        let mut bits = Vec::with_capacity(n);
        let mut enc = ZpEncoder::new();
        let mut ctx = vec![0u8; nctx];

        for i in 0..n {
            rng ^= rng << 13;
            rng ^= rng >> 7;
            rng ^= rng << 17;
            let bit = (rng & 1) != 0;
            bits.push((i % nctx, bit));
            enc.encode_bit(&mut ctx[i % nctx], bit);
        }
        let compressed = enc.finish();

        let mut dec = ZpDecoder::new(&compressed).expect("init");
        let mut dec_ctx = vec![0u8; nctx];
        for (i, &(ci, expected)) in bits.iter().enumerate() {
            let got = dec.decode_bit(&mut dec_ctx[ci]);
            assert_eq!(got, expected, "mismatch at bit {i} ctx {ci}");
        }
    }
}

//! ZP adaptive binary arithmetic coder — pure-Rust clean-room implementation.
//!
//! This crate implements the ZP (Z-Prime) adaptive binary arithmetic coder
//! from the DjVu v3 specification (<https://www.sndjvu.org/spec.html>),
//! used by the JB2, IW44, and BZZ codecs that make up a DjVu file.
//!
//! ## Usage
//!
//! Decoder (no_std-capable, no allocations):
//!
//! ```
//! use djvu_zp::ZpDecoder;
//! let compressed: &[u8] = &[0x00, 0x00];
//! let mut dec = ZpDecoder::new(compressed)?;
//! let mut ctx = 0u8;
//! let _bit = dec.decode_bit(&mut ctx);
//! # Ok::<(), djvu_zp::ZpError>(())
//! ```
//!
//! Encoder (requires `std` feature, default-on):
//!
//! ```
//! # #[cfg(feature = "std")]
//! # {
//! use djvu_zp::encoder::ZpEncoder;
//! let mut enc = ZpEncoder::new();
//! let mut ctx = 0u8;
//! enc.encode_bit(&mut ctx, true);
//! let _bytes: Vec<u8> = enc.finish();
//! # }
//! ```
//!
//! ## Features
//!
//! - `std` (default) — enables [`encoder::ZpEncoder`].  The decoder works
//!   with or without `std` and never allocates.

#![cfg_attr(not(feature = "std"), no_std)]

#[cfg(feature = "std")]
pub mod encoder;
pub mod tables;

use tables::{LPS_NEXT, MPS_NEXT, PROB, THRESHOLD};

/// Errors that can occur while initializing or decoding a ZP stream.
#[derive(Debug, thiserror::Error, PartialEq, Eq)]
pub enum ZpError {
    /// Input is too short — the ZP coder needs at least 2 bytes to load the
    /// initial code register.
    #[error("ZP input is too short (need at least 2 bytes)")]
    TooShort,
}

/// ZP (Z-Prime) adaptive binary arithmetic decoder.
///
/// Implements the decoder described in the DjVu v3 specification. The decoder
/// maintains a probability model for each context and adapts the model as bits
/// are decoded.
///
/// Context bytes encode both the probability state index and the current MPS
/// (most probable symbol) value. The low bit of the context byte indicates
/// the current MPS; the remaining bits encode the probability state.
pub struct ZpDecoder<'a> {
    /// Current interval width register (16-bit value held in low 16 bits).
    pub a: u32,
    /// Current code (value within the interval) register (16-bit value held in low 16 bits).
    pub c: u32,
    /// Cached upper bound for the fast decode path (= min(c, 0x7fff)).
    pub fence: u32,
    /// Bit buffer for feeding bits into the code register.
    pub bit_buf: u32,
    /// Number of valid bits remaining in `bit_buf`.
    pub bit_count: i32,
    /// Compressed input bytes.
    pub data: &'a [u8],
    /// Current read position within `data`.
    ///
    /// Advances by one for every byte the coder consumes, **including synthetic
    /// `0xFF` padding read past the end of `data`** — it is not clamped at
    /// `data.len()`. The overshoot `pos - data.len()` is therefore the number of
    /// synthetic bytes emitted so far; see [`synthetic_bytes`](Self::synthetic_bytes).
    /// Every byte reader (this struct's [`read_byte`](Self::read_byte) and the
    /// inlined hot-path readers in djvu-jb2 / djvu-iw44 / djvu-bzz) advances `pos`
    /// the same way, so the overshoot is consistent regardless of which path read.
    pub pos: usize,
}

impl<'a> ZpDecoder<'a> {
    /// Construct a new ZP decoder from the given compressed byte slice.
    ///
    /// Reads the initial code register from the first two bytes of `data`.
    ///
    /// # Errors
    ///
    /// Returns [`ZpError::TooShort`] if `data` has fewer than 2 bytes.
    pub fn new(data: &'a [u8]) -> Result<Self, ZpError> {
        if data.len() < 2 {
            return Err(ZpError::TooShort);
        }

        let mut dec = ZpDecoder {
            a: 0,
            c: 0,
            fence: 0,
            bit_buf: 0,
            bit_count: 0,
            data,
            pos: 0,
        };

        // Load the initial code register from the first two bytes
        let high = dec.read_byte() as u32;
        let low = dec.read_byte() as u32;
        dec.c = (high << 8) | low;

        // Pre-fill the bit buffer
        dec.refill_buffer();

        // Initialise the fence
        dec.fence = dec.c.min(0x7fff);

        Ok(dec)
    }

    /// Read the next byte from the input stream, returning `0xFF` on exhaustion.
    ///
    /// `pos` advances on every call, even past the end of `data`, so that the
    /// overshoot `pos - data.len()` counts synthetic padding (see
    /// [`synthetic_bytes`](Self::synthetic_bytes)). This matches the inlined
    /// hot-path byte readers in djvu-jb2 / djvu-iw44 / djvu-bzz, keeping the
    /// synthetic-byte count consistent no matter which reader consumed the byte.
    #[inline(always)]
    fn read_byte(&mut self) -> u8 {
        let b = if self.pos < self.data.len() {
            self.data[self.pos]
        } else {
            0xff
        };
        self.pos = self.pos.wrapping_add(1);
        b
    }

    /// Fill `bit_buf` with fresh bytes until it holds at least 24 bits.
    #[inline(always)]
    fn refill_buffer(&mut self) {
        while self.bit_count <= 24 {
            let byte = self.read_byte();
            self.bit_buf = (self.bit_buf << 8) | (byte as u32);
            self.bit_count += 8;
        }
    }

    /// Decode one bit using an adaptive probability context.
    ///
    /// `ctx` is a mutable context byte encoding the current probability state
    /// and MPS value. It is updated in-place after each call.
    ///
    /// Returns `true` if the decoded bit is 1.
    #[inline(always)]
    pub fn decode_bit(&mut self, ctx: &mut u8) -> bool {
        let state = *ctx as usize;
        let mps_bit = state & 1; // low bit encodes the current MPS
        let z = self.a + PROB[state] as u32;

        // Fast path: interval stays within the fence — no renormalization needed
        if z <= self.fence {
            self.a = z;
            return mps_bit != 0;
        }

        // Clamp to the decision boundary
        let boundary = 0x6000u32 + ((self.a + z) >> 2);
        let z_clamped = z.min(boundary);

        if z_clamped > self.c {
            // LPS event: decoded bit is opposite of MPS
            let lps_bit = 1 - mps_bit;
            let complement = 0x10000u32 - z_clamped;
            self.a = (self.a + complement) & 0xffff;
            self.c = (self.c + complement) & 0xffff;
            *ctx = LPS_NEXT[state];
            self.renormalize();
            lps_bit != 0
        } else {
            // MPS event: decoded bit matches MPS
            if self.a >= THRESHOLD[state] as u32 {
                *ctx = MPS_NEXT[state];
            }
            self.bit_count -= 1;
            self.a = (z_clamped << 1) & 0xffff;
            self.c = (self.c << 1 | (self.bit_buf >> self.bit_count as u32) & 1) & 0xffff;
            if self.bit_count < 16 {
                self.refill_buffer();
            }
            self.fence = self.c.min(0x7fff);
            mps_bit != 0
        }
    }

    /// Returns `true` once all real input bytes have been consumed.
    ///
    /// After exhaustion the coder returns `0xFF` bytes indefinitely, producing
    /// deterministic but meaningless bits. Callers may use this to skip
    /// remaining work that would otherwise loop on constant input.
    pub fn is_exhausted(&self) -> bool {
        self.pos >= self.data.len()
    }

    /// Number of synthetic `0xFF` bytes emitted past the end of the real input.
    ///
    /// Computed as the overshoot of [`pos`](Self::pos) beyond `data.len()`. Every
    /// byte reader — this struct's [`read_byte`](Self::read_byte) and the inlined
    /// hot-path readers in djvu-jb2 / djvu-iw44 / djvu-bzz — advances `pos` past
    /// the end of `data` on each post-EOF read, so this is the true total across
    /// all of them.
    ///
    /// Unlike [`is_exhausted`](Self::is_exhausted), which flips as soon as the
    /// *byte* buffer drains — several bytes before the logical end of the
    /// arithmetic stream, because the decoder buffers up to 32 bits of
    /// look-ahead — this counts only genuine post-EOF padding reads. It lets a
    /// caller tell "finishing the last buffered bits of a valid stream" (a
    /// handful of synthetic bytes) apart from "spinning on exhausted input"
    /// (unbounded), which `is_exhausted` cannot distinguish.
    pub fn synthetic_bytes(&self) -> usize {
        self.pos.saturating_sub(self.data.len())
    }

    /// Decode one bit in passthrough (context-free) mode.
    ///
    /// Used by BZZ to decode raw integer values (block size, BWT index).
    /// The threshold is `z = 0x8000 + (a >> 1)`.
    ///
    /// Returns `true` if the decoded bit is 1.
    #[inline(always)]
    pub fn decode_passthrough(&mut self) -> bool {
        let z = (0x8000u32 + (self.a >> 1)) as u16;
        self.passthrough_with_threshold(z)
    }

    /// Decode one bit in IW44 passthrough mode.
    ///
    /// The threshold is `z = 0x8000 + (3 * a / 8)`.
    ///
    /// Returns `true` if the decoded bit is 1.
    #[inline(always)]
    pub fn decode_passthrough_iw44(&mut self) -> bool {
        let z = (0x8000u32 + (3u32 * self.a) / 8) as u16;
        self.passthrough_with_threshold(z)
    }

    /// Internal passthrough decode with an explicit threshold `z`.
    #[inline(always)]
    fn passthrough_with_threshold(&mut self, z: u16) -> bool {
        if z as u32 > self.c {
            // Bit is 1
            let complement = 0x10000u32 - z as u32;
            self.a = (self.a + complement) & 0xffff;
            self.c = (self.c + complement) & 0xffff;
            self.renormalize();
            true
        } else {
            // Bit is 0
            self.bit_count -= 1;
            self.a = (z as u32 * 2) & 0xffff;
            self.c = (self.c << 1 | (self.bit_buf >> self.bit_count as u32) & 1) & 0xffff;
            if self.bit_count < 16 {
                self.refill_buffer();
            }
            self.fence = self.c.min(0x7fff);
            false
        }
    }

    /// Renormalize after an LPS event.
    ///
    /// Shifts the interval register left until `a >= 0x8000`, pulling fresh bits
    /// into `c` from the bit buffer.
    #[inline(always)]
    fn renormalize(&mut self) {
        let shift = (self.a as u16).leading_ones();
        self.bit_count -= shift as i32;
        self.a = (self.a << shift) & 0xffff;
        let mask = (1u32 << shift) - 1;
        self.c = ((self.c << shift) | (self.bit_buf >> self.bit_count as u32) & mask) & 0xffff;
        if self.bit_count < 16 {
            self.refill_buffer();
        }
        self.fence = self.c.min(0x7fff);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn zp_decoder_rejects_empty_input() {
        assert!(matches!(ZpDecoder::new(&[]), Err(ZpError::TooShort)));
    }

    #[test]
    fn zp_decoder_rejects_one_byte_input() {
        assert!(matches!(ZpDecoder::new(&[0x00]), Err(ZpError::TooShort)));
    }

    #[test]
    fn zp_decoder_accepts_two_byte_input() {
        assert!(ZpDecoder::new(&[0x00, 0x00]).is_ok());
        assert!(ZpDecoder::new(&[0xff, 0xff]).is_ok());
    }

    #[test]
    fn synthetic_bytes_distinguishes_eof_from_spinning() {
        // `new()` always consumes 6 bytes: a 2-byte code load plus a 4-byte
        // initial `refill_buffer`. With exactly 6 bytes the byte buffer is
        // drained (`is_exhausted`) yet NO synthetic padding was needed — this
        // is the valid-tail case the JB2 budget guard must not treat as
        // "spinning". `is_exhausted()` alone cannot tell it apart.
        let zp = ZpDecoder::new(&[0u8; 6]).unwrap();
        assert!(zp.is_exhausted(), "pos reached end of input");
        assert_eq!(
            zp.synthetic_bytes(),
            0,
            "no padding read despite exhaustion"
        );

        // A 2-byte stream forces the entire 4-byte refill from synthetic fill.
        let zp2 = ZpDecoder::new(&[0u8; 2]).unwrap();
        assert!(zp2.is_exhausted());
        assert_eq!(zp2.synthetic_bytes(), 4, "refill faked 4 bytes past EOF");

        // Ample input: neither exhausted nor padded.
        let zp3 = ZpDecoder::new(&[0u8; 64]).unwrap();
        assert!(!zp3.is_exhausted());
        assert_eq!(zp3.synthetic_bytes(), 0);

        // Decoding on past EOF accumulates padding without bound, blowing past
        // any fixed slack — the signal that the stream is genuinely spinning.
        let mut zp4 = ZpDecoder::new(&[0u8; 2]).unwrap();
        let mut ctx = 0u8;
        for _ in 0..10_000 {
            let _ = zp4.decode_bit(&mut ctx);
        }
        assert!(
            zp4.synthetic_bytes() > 16,
            "spinning should exceed the slack, got {}",
            zp4.synthetic_bytes()
        );
    }

    #[test]
    fn zp_tables_spot_check() {
        // These values are from the DjVu v3 spec
        assert_eq!(PROB[0], 0x8000);
        assert_eq!(PROB[250], 0x481a);
        assert_eq!(MPS_NEXT[0], 84);
        assert_eq!(LPS_NEXT[0], 145);
        assert_eq!(THRESHOLD[83], 0);
        assert_eq!(THRESHOLD[250], 0);
    }
}

use std::sync::Arc;

use pyo3::exceptions::{PyIOError, PyIndexError, PyValueError};
use pyo3::prelude::*;
use pyo3::types::PyBytes;

/// A DjVu document.
#[pyclass]
struct Document {
    inner: Arc<djvu_rs::Document>,
}

#[pymethods]
impl Document {
    /// Open a DjVu document from a file path.
    #[staticmethod]
    fn open(path: &str) -> PyResult<Self> {
        let data = std::fs::read(path).map_err(|e| PyIOError::new_err(format!("{e}")))?;
        let doc = djvu_rs::Document::from_bytes(data)
            .map_err(|e| PyValueError::new_err(format!("{e}")))?;
        Ok(Document {
            inner: Arc::new(doc),
        })
    }

    /// Open a DjVu document from bytes.
    #[staticmethod]
    fn from_bytes(data: &[u8]) -> PyResult<Self> {
        let doc = djvu_rs::Document::from_bytes(data.to_vec())
            .map_err(|e| PyValueError::new_err(format!("{e}")))?;
        Ok(Document {
            inner: Arc::new(doc),
        })
    }

    /// Number of pages in the document.
    fn page_count(&self) -> usize {
        self.inner.page_count()
    }

    /// Get a page by index (0-based).
    fn page(&self, index: usize) -> PyResult<Page> {
        let p = self
            .inner
            .page(index)
            .map_err(|e| PyIndexError::new_err(format!("{e}")))?;
        Ok(Page {
            width: p.width(),
            height: p.height(),
            dpi: p.dpi(),
            doc: Arc::clone(&self.inner),
            index,
        })
    }
}

/// A page within a DjVu document.
#[pyclass]
struct Page {
    width: u32,
    height: u32,
    dpi: u16,
    doc: Arc<djvu_rs::Document>,
    index: usize,
}

#[pymethods]
impl Page {
    /// Page width in pixels.
    #[getter]
    fn width(&self) -> u32 {
        self.width
    }

    /// Page height in pixels.
    #[getter]
    fn height(&self) -> u32 {
        self.height
    }

    /// Page DPI.
    #[getter]
    fn dpi(&self) -> u16 {
        self.dpi
    }

    /// Render the page as RGBA bytes.
    ///
    /// Args:
    ///     dpi: Target DPI. If not specified, renders at native DPI.
    ///
    /// Returns:
    ///     Pixmap with width, height, and RGBA data.
    #[pyo3(signature = (dpi=None))]
    fn render(&self, dpi: Option<f32>) -> PyResult<Pixmap> {
        let page = self
            .doc
            .page(self.index)
            .map_err(|e| PyIndexError::new_err(format!("{e}")))?;

        let pixmap = if let Some(target_dpi) = dpi {
            let scale = target_dpi / self.dpi as f32;
            let w = ((self.width as f32 * scale).round() as u32).max(1);
            let h = ((self.height as f32 * scale).round() as u32).max(1);
            page.render_to_size(w, h)
        } else {
            page.render()
        }
        .map_err(|e| PyValueError::new_err(format!("render failed: {e}")))?;

        Ok(Pixmap {
            width: pixmap.width,
            height: pixmap.height,
            data: pixmap.data,
        })
    }

    /// Extract the text layer from this page.
    ///
    /// Returns None if no text layer is present.
    fn text(&self) -> PyResult<Option<String>> {
        let page = self
            .doc
            .page(self.index)
            .map_err(|e| PyIndexError::new_err(format!("{e}")))?;
        page.text()
            .map_err(|e| PyValueError::new_err(format!("{e}")))
    }
}

/// An RGBA pixel buffer.
#[pyclass]
struct Pixmap {
    width: u32,
    height: u32,
    data: Vec<u8>,
}

#[pymethods]
impl Pixmap {
    /// Image width in pixels.
    #[getter]
    fn width(&self) -> u32 {
        self.width
    }

    /// Image height in pixels.
    #[getter]
    fn height(&self) -> u32 {
        self.height
    }

    /// RGBA pixel data as bytes (length = width * height * 4).
    fn data<'py>(&self, py: Python<'py>) -> Bound<'py, PyBytes> {
        PyBytes::new(py, &self.data)
    }

    /// Convert to a numpy array (requires numpy).
    ///
    /// Returns a numpy.ndarray with shape (height, width, 4) and dtype uint8.
    fn to_numpy<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
        let numpy = py.import("numpy")?;
        let frombuffer = numpy.getattr("frombuffer")?;
        let bytes = PyBytes::new(py, &self.data);
        let arr = frombuffer.call1((bytes, numpy.getattr("uint8")?))?;
        arr.call_method1("reshape", ((self.height, self.width, 4u32),))
    }

    /// Convert to a PIL Image (requires Pillow).
    ///
    /// Returns a PIL.Image.Image in RGBA mode.
    fn to_pil<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
        let pil = py.import("PIL.Image")?;
        let frombytes = pil.getattr("frombytes")?;
        let size = (self.width, self.height);
        let bytes = PyBytes::new(py, &self.data);
        frombytes.call1(("RGBA", size, bytes))
    }
}

/// Python module definition.
#[pymodule(name = "djvu_rs")]
fn djvu_rs_module(m: &Bound<'_, PyModule>) -> PyResult<()> {
    m.add_class::<Document>()?;
    m.add_class::<Page>()?;
    m.add_class::<Pixmap>()?;
    Ok(())
}

//! Bisect issue #199: which layer (mask, BG, FG) of colorbook.djvu p0
//! diverges from DjVuLibre?
//!
//! Approach: read djvu-rs's per-layer accessors, read ddjvu's per-mode
//! PPM/PBM outputs, compute pixelwise mismatch% (tolerance 4 like the
//! main diff harness) per layer.

use djvu_rs::djvu_document::DjVuDocument;
use std::env;

fn read_ppm(path: &str) -> (u32, u32, Vec<u8>) {
    // Minimal P6 PPM reader: "P6\n<W> <H>\n<MAX>\n<RGB bytes>"
    let bytes = std::fs::read(path).unwrap();
    let mut i = 0;
    fn skip_ws(b: &[u8], i: &mut usize) {
        while *i < b.len() && (b[*i] == b' ' || b[*i] == b'\n' || b[*i] == b'\r' || b[*i] == b'\t')
        {
            *i += 1;
        }
        while *i < b.len() && b[*i] == b'#' {
            while *i < b.len() && b[*i] != b'\n' {
                *i += 1;
            }
            while *i < b.len() && (b[*i] == b' ' || b[*i] == b'\n' || b[*i] == b'\r') {
                *i += 1;
            }
        }
    }
    fn token(b: &[u8], i: &mut usize) -> String {
        skip_ws(b, i);
        let s = *i;
        while *i < b.len() && b[*i] != b' ' && b[*i] != b'\n' && b[*i] != b'\r' && b[*i] != b'\t' {
            *i += 1;
        }
        String::from_utf8_lossy(&b[s..*i]).to_string()
    }
    let magic = token(&bytes, &mut i);
    let w: u32 = token(&bytes, &mut i).parse().unwrap();
    let h: u32 = token(&bytes, &mut i).parse().unwrap();
    let max: u32 = token(&bytes, &mut i).parse().unwrap();
    assert_eq!(max, 255);
    // skip the single whitespace after maxval
    while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\n' || bytes[i] == b'\r') {
        i += 1;
    }
    let body = bytes[i..].to_vec();
    if magic == "P6" {
        (w, h, body)
    } else if magic == "P5" {
        // grayscale, expand to RGB
        let mut rgb = Vec::with_capacity(body.len() * 3);
        for &g in &body {
            rgb.push(g);
            rgb.push(g);
            rgb.push(g);
        }
        (w, h, rgb)
    } else {
        panic!("unsupported PPM magic: {magic}");
    }
}

fn read_pbm(path: &str) -> (u32, u32, Vec<u8>) {
    // P4 PBM reader
    let bytes = std::fs::read(path).unwrap();
    let mut i = 0;
    let mut tok = || {
        while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\n' || bytes[i] == b'\r') {
            i += 1;
        }
        while i < bytes.len() && bytes[i] == b'#' {
            while i < bytes.len() && bytes[i] != b'\n' {
                i += 1;
            }
            while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\n' || bytes[i] == b'\r') {
                i += 1;
            }
        }
        let s = i;
        while i < bytes.len()
            && bytes[i] != b' '
            && bytes[i] != b'\n'
            && bytes[i] != b'\r'
            && bytes[i] != b'\t'
        {
            i += 1;
        }
        String::from_utf8_lossy(&bytes[s..i]).to_string()
    };
    let magic = tok();
    assert_eq!(magic, "P4");
    let w: u32 = tok().parse().unwrap();
    let h: u32 = tok().parse().unwrap();
    while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\n' || bytes[i] == b'\r') {
        i += 1;
    }
    // body: ceil(w/8) bytes per row, MSB-first, 0=white 1=black
    let stride = (w as usize).div_ceil(8);
    let mut out = vec![255u8; (w * h) as usize];
    for y in 0..h as usize {
        for x in 0..w as usize {
            let by = bytes[i + y * stride + (x / 8)];
            let bit = (by >> (7 - (x % 8))) & 1;
            if bit == 1 {
                out[y * w as usize + x] = 0;
            }
        }
    }
    (w, h, out)
}

fn diff_rgb(a: &[u8], b: &[u8]) -> (usize, u32, f64) {
    let mut mismatch = 0;
    let mut max = 0u32;
    let mut sum = 0u64;
    let mut count = 0u64;
    for (x, y) in a.chunks_exact(3).zip(b.chunks_exact(3)) {
        let d = (x[0] as i32 - y[0] as i32)
            .abs()
            .max((x[1] as i32 - y[1] as i32).abs())
            .max((x[2] as i32 - y[2] as i32).abs()) as u32;
        if d > 4 {
            mismatch += 1;
        }
        max = max.max(d);
        sum += d as u64;
        count += 1;
    }
    (mismatch, max, sum as f64 / count.max(1) as f64)
}

fn diff_gray(a: &[u8], b: &[u8]) -> (usize, u32, f64) {
    let mut mismatch = 0;
    let mut max = 0u32;
    let mut sum = 0u64;
    for (x, y) in a.iter().zip(b.iter()) {
        let d = (*x as i32 - *y as i32).unsigned_abs();
        if d > 4 {
            mismatch += 1;
        }
        max = max.max(d);
        sum += d as u64;
    }
    (mismatch, max, sum as f64 / a.len().max(1) as f64)
}

fn main() {
    let djvu_path = env::args()
        .nth(1)
        .unwrap_or_else(|| "tests/fixtures/colorbook.djvu".into());
    let bg_ref = env::args()
        .nth(2)
        .unwrap_or_else(|| "/tmp/diff199/p0_bg_native.ppm".into());
    let _fg_ref = env::args()
        .nth(3)
        .unwrap_or_else(|| "/tmp/diff199/p0_fg_native.ppm".into());
    let mask_ref = env::args()
        .nth(4)
        .unwrap_or_else(|| "/tmp/diff199/p0_mask_native.pbm".into());

    let bytes = std::fs::read(&djvu_path).unwrap();
    let doc = DjVuDocument::parse(&bytes).unwrap();
    let page = doc.page(0).unwrap();
    let pw = page.width() as u32;
    let ph = page.height() as u32;
    println!("djvu-rs page 0: {pw}x{ph}");

    // ── Mask ───────────────────────────────────────────────────────────
    if let Some(mask) = page.extract_mask().ok().flatten() {
        println!("djvu-rs decoded_mask: {}x{}", mask.width, mask.height);
        let mut mask_gray = vec![255u8; (mask.width * mask.height) as usize];
        for y in 0..mask.height {
            for x in 0..mask.width {
                if mask.get(x, y) {
                    mask_gray[(y * mask.width + x) as usize] = 0;
                }
            }
        }
        let (rw, rh, rgray) = read_pbm(&mask_ref);
        println!("ddjvu mask: {rw}x{rh}");
        if rw == mask.width && rh == mask.height {
            let (mm, mx, mn) = diff_gray(&mask_gray, &rgray);
            let total = (mask.width * mask.height) as usize;
            println!(
                "  mask: mismatch {} / {} ({:.2}%), max Δ={}, mean Δ={:.3}",
                mm,
                total,
                100.0 * mm as f64 / total as f64,
                mx,
                mn
            );
        } else {
            println!("  mask: dimension mismatch — skipping diff");
        }
    } else {
        println!("djvu-rs decoded_mask: NONE");
    }

    // ── BG44 ───────────────────────────────────────────────────────────
    if let Some(bg) = page.decoded_bg44() {
        let pm = bg.to_rgb().unwrap();
        println!("djvu-rs decoded_bg44.to_rgb: {}x{}", pm.width, pm.height);
        let rgb_only: Vec<u8> = pm
            .data
            .chunks_exact(4)
            .flat_map(|c| [c[0], c[1], c[2]])
            .collect();
        let (rw, rh, rrgb) = read_ppm(&bg_ref);
        println!("ddjvu bg: {rw}x{rh}");
        // Crop both to the common rectangle (ddjvu floors width while
        // decoded_bg44 takes from the chunk header — off-by-one widths).
        let cw = pm.width.min(rw);
        let ch = pm.height.min(rh);
        let crop = |src: &[u8], src_w: u32, w: u32, h: u32| -> Vec<u8> {
            let mut v = Vec::with_capacity((w * h * 3) as usize);
            for y in 0..h {
                let row = &src[((y * src_w * 3) as usize)..((y * src_w * 3 + w * 3) as usize)];
                v.extend_from_slice(row);
            }
            v
        };
        let a = crop(&rgb_only, pm.width, cw, ch);
        let b = crop(&rrgb, rw, cw, ch);
        let (mm, mx, mn) = diff_rgb(&a, &b);
        let total = (cw * ch) as usize;
        println!(
            "  bg ({cw}x{ch} crop): mismatch {} / {} ({:.2}%), max Δ={}, mean Δ={:.3}",
            mm,
            total,
            100.0 * mm as f64 / total as f64,
            mx,
            mn
        );
    } else {
        println!("djvu-rs decoded_bg44: NONE");
    }

    // ── FG44 ───────────────────────────────────────────────────────────
    if let Some(fg) = page.extract_foreground().ok().flatten() {
        println!("djvu-rs decoded_fg44: {}x{}", fg.width, fg.height);
        let rgb_only: Vec<u8> = fg
            .data
            .chunks_exact(4)
            .flat_map(|c| [c[0], c[1], c[2]])
            .collect();
        let (rw, rh, rrgb) = read_ppm(&_fg_ref);
        println!("ddjvu fg: {rw}x{rh}");
        let cw = fg.width.min(rw);
        let ch = fg.height.min(rh);
        let crop = |src: &[u8], src_w: u32, w: u32, h: u32| -> Vec<u8> {
            let mut v = Vec::with_capacity((w * h * 3) as usize);
            for y in 0..h {
                let row = &src[((y * src_w * 3) as usize)..((y * src_w * 3 + w * 3) as usize)];
                v.extend_from_slice(row);
            }
            v
        };
        let a = crop(&rgb_only, fg.width, cw, ch);
        let b = crop(&rrgb, rw, cw, ch);
        let (mm, mx, mn) = diff_rgb(&a, &b);
        let total = (cw * ch) as usize;
        println!(
            "  fg ({cw}x{ch} crop): mismatch {} / {} ({:.2}%), max Δ={}, mean Δ={:.3}",
            mm,
            total,
            100.0 * mm as f64 / total as f64,
            mx,
            mn
        );
        // Sample a few pixels for sanity:
        for &(sx, sy) in &[(0u32, 0u32), (50, 100), (100, 200), (180, 300)] {
            if sx < cw && sy < ch {
                let i = ((sy * cw + sx) * 3) as usize;
                println!(
                    "    pixel ({sx},{sy}): djvu-rs=({},{},{}) ddjvu=({},{},{})",
                    a[i],
                    a[i + 1],
                    a[i + 2],
                    b[i],
                    b[i + 1],
                    b[i + 2]
                );
            }
        }
    } else {
        println!("djvu-rs decoded_fg44: NONE");
    }
}

use djvu_rs::{DjVuDocument, jb2, jb2_encode::encode_jb2};

fn main() {
    let path = std::env::args().nth(1).expect("path");
    let page_idx: usize = std::env::args()
        .nth(2)
        .unwrap_or_else(|| "0".into())
        .parse()
        .unwrap();
    let data = std::fs::read(&path).unwrap();
    let doc = DjVuDocument::parse(&data).unwrap();
    let page = doc.page(page_idx).unwrap();
    let bitmap = page.extract_mask().unwrap().unwrap();
    println!("original bitmap: {}x{}", bitmap.width, bitmap.height);

    let rs = encode_jb2(&bitmap);
    println!("encoded size: {}", rs.len());

    print!("first 32 bytes: ");
    for b in rs.iter().take(32) {
        print!("{:02x} ", b);
    }
    println!();

    match jb2::decode(&rs, None) {
        Ok(b) => println!(
            "redecoded: {}x{}  data_eq: {}",
            b.width,
            b.height,
            b.data == bitmap.data
        ),
        Err(e) => println!("redecode failed: {}", e),
    }
}

use djvu_rs::DjVuDocument;
fn main() {
    let data = std::fs::read("tests/corpus/watchmaker.djvu").unwrap();
    let doc = DjVuDocument::parse(&data).unwrap();
    let p = doc.page(1).unwrap();
    let layer = p.text_layer().unwrap().unwrap();
    let text = &layer.text;
    let mut counts = std::collections::HashMap::<char, usize>::new();
    for c in text.chars() {
        if (c as u32) < 32 || c == '\x7f' {
            *counts.entry(c).or_default() += 1;
        }
    }
    for (c, n) in counts {
        println!("{:#04x} ({:?}): {}", c as u32, c, n);
    }
    println!("---First 600 chars (ctrls escaped)---");
    let preview: String = text
        .chars()
        .take(600)
        .map(|c| {
            if (c as u32) < 32 {
                format!("{{{:02x}}}", c as u32)
            } else {
                c.to_string()
            }
        })
        .collect();
    println!("{}", preview);
}

use djvu_rs::DjVuDocument;
use djvu_rs::text::{TextZone, TextZoneKind};
fn dump(z: &TextZone, depth: usize) {
    let kind = format!("{:?}", z.kind);
    let preview: String = z.text.chars().take(40).collect();
    println!(
        "{}{} {}x{}+{}+{} | {:?}",
        "  ".repeat(depth),
        kind,
        z.rect.width,
        z.rect.height,
        z.rect.x,
        z.rect.y,
        preview
    );
    if matches!(
        z.kind,
        TextZoneKind::Page | TextZoneKind::Column | TextZoneKind::Region | TextZoneKind::Para
    ) {
        for c in &z.children {
            dump(c, depth + 1);
        }
    }
}
fn main() {
    let data = std::fs::read("tests/corpus/watchmaker.djvu").unwrap();
    let doc = DjVuDocument::parse(&data).unwrap();
    let p = doc.page(1).unwrap();
    let layer = p.text_layer().unwrap().unwrap();
    for z in &layer.zones {
        dump(z, 0);
    }
}

//! Ad-hoc helper: dump per-chunk byte sizes for page 0 of a DjVu file.
//! Used to bisect issue #199 (colorbook.djvu render divergence).

use djvu_rs::djvu_document::DjVuDocument;
use std::env;

fn main() {
    let path = env::args().nth(1).expect("usage: _inspect_page0 <file>");
    let bytes = std::fs::read(&path).unwrap();
    let doc = DjVuDocument::parse(&bytes).unwrap();
    let page = doc.page(0).unwrap();

    println!(
        "page 0 of {path}: {}x{} px @ {} dpi",
        page.width(),
        page.height(),
        page.dpi()
    );
    for id in page.chunk_ids() {
        let total: usize = page.all_chunks(&id).iter().map(|c| c.len()).sum();
        let count = page.all_chunks(&id).len();
        println!(
            "  {} : {} chunk(s), {} bytes",
            String::from_utf8_lossy(&id),
            count,
            total
        );
    }
}

//! Pixel-by-pixel compare two PPMs, sample N random differences with
//! mask/bg/fg context for issue #199.

use djvu_rs::djvu_document::DjVuDocument;
use std::env;

fn read_ppm(path: &str) -> (u32, u32, Vec<u8>) {
    let bytes = std::fs::read(path).unwrap();
    let mut i = 0;
    let mut tok = || {
        while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\n' || bytes[i] == b'\r') {
            i += 1;
        }
        while i < bytes.len() && bytes[i] == b'#' {
            while i < bytes.len() && bytes[i] != b'\n' {
                i += 1;
            }
            while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\n' || bytes[i] == b'\r') {
                i += 1;
            }
        }
        let s = i;
        while i < bytes.len()
            && bytes[i] != b' '
            && bytes[i] != b'\n'
            && bytes[i] != b'\r'
            && bytes[i] != b'\t'
        {
            i += 1;
        }
        String::from_utf8_lossy(&bytes[s..i]).to_string()
    };
    assert_eq!(tok(), "P6");
    let w: u32 = tok().parse().unwrap();
    let h: u32 = tok().parse().unwrap();
    let m: u32 = tok().parse().unwrap();
    assert_eq!(m, 255);
    while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\n' || bytes[i] == b'\r') {
        i += 1;
    }
    (w, h, bytes[i..].to_vec())
}

fn main() {
    let djvu_path = env::args().nth(1).unwrap();
    let our_path = env::args().nth(2).unwrap();
    let ref_path = env::args().nth(3).unwrap();

    let (ow, oh, o) = read_ppm(&our_path);
    let (rw, rh, r) = read_ppm(&ref_path);
    println!("ours: {ow}x{oh}, ref: {rw}x{rh}");
    let w = ow.min(rw);
    let h = oh.min(rh);

    let bytes = std::fs::read(&djvu_path).unwrap();
    let doc = DjVuDocument::parse(&bytes).unwrap();
    let page = doc.page(0).unwrap();
    let mask = page.extract_mask().ok().flatten();
    let fg = page.extract_foreground().ok().flatten();
    let bg = page.decoded_bg44();
    println!(
        "page: {}x{}, fg44: {:?}, bg44: {:?}, mask: {:?}",
        page.width(),
        page.height(),
        fg.as_ref().map(|f| (f.width, f.height)),
        bg.as_ref().map(|b| (b.width, b.height)),
        mask.as_ref().map(|m| (m.width, m.height)),
    );

    // Sample 20 mismatched pixels: find first 20 with abs diff > 4.
    let mut mask_on_mm = 0u64;
    let mut mask_on_total = 0u64;
    let mut mask_off_mm = 0u64;
    let mut mask_off_total = 0u64;
    let mut sum_mask_on = (0i64, 0i64, 0i64);
    let mut sum_mask_off = (0i64, 0i64, 0i64);
    for y in 0..h {
        for x in 0..w {
            let i = ((y * ow + x) * 3) as usize;
            let j = ((y * rw + x) * 3) as usize;
            let d = (o[i] as i32 - r[j] as i32)
                .abs()
                .max((o[i + 1] as i32 - r[j + 1] as i32).abs())
                .max((o[i + 2] as i32 - r[j + 2] as i32).abs());
            let m = mask
                .as_ref()
                .map(|m| {
                    if x < m.width && y < m.height {
                        m.get(x, y) as u8
                    } else {
                        0
                    }
                })
                .unwrap_or(0);
            let dr = o[i] as i32 - r[j] as i32;
            let dg = o[i + 1] as i32 - r[j + 1] as i32;
            let db = o[i + 2] as i32 - r[j + 2] as i32;
            if m == 1 {
                mask_on_total += 1;
                if d > 4 {
                    mask_on_mm += 1;
                }
                sum_mask_on.0 += dr as i64;
                sum_mask_on.1 += dg as i64;
                sum_mask_on.2 += db as i64;
            } else {
                mask_off_total += 1;
                if d > 4 {
                    mask_off_mm += 1;
                }
                sum_mask_off.0 += dr as i64;
                sum_mask_off.1 += dg as i64;
                sum_mask_off.2 += db as i64;
            }
        }
    }
    println!(
        "mask=1 (FG): {} / {} mismatched ({:.2}%), mean Δ rgb = ({:.2},{:.2},{:.2})",
        mask_on_mm,
        mask_on_total,
        100.0 * mask_on_mm as f64 / mask_on_total.max(1) as f64,
        sum_mask_on.0 as f64 / mask_on_total.max(1) as f64,
        sum_mask_on.1 as f64 / mask_on_total.max(1) as f64,
        sum_mask_on.2 as f64 / mask_on_total.max(1) as f64,
    );
    println!(
        "mask=0 (BG): {} / {} mismatched ({:.2}%), mean Δ rgb = ({:.2},{:.2},{:.2})",
        mask_off_mm,
        mask_off_total,
        100.0 * mask_off_mm as f64 / mask_off_total.max(1) as f64,
        sum_mask_off.0 as f64 / mask_off_total.max(1) as f64,
        sum_mask_off.1 as f64 / mask_off_total.max(1) as f64,
        sum_mask_off.2 as f64 / mask_off_total.max(1) as f64,
    );
}

// Probe for #258: identify shared symbols whose dimensions exceed
// MAX_SYMBOL_PIXELS (1 MP) — these would fail decode_bitmap_direct/ref
// after `cluster_shared_symbols_tunable` puts them into the shared Djbz.

use djvu_rs::Bitmap;
use djvu_rs::djvu_document::DjVuDocument;
use djvu_rs::jb2::decode_dict;
use djvu_rs::jb2_encode::{
    cluster_shared_symbols_tunable, encode_djvm_bundle_jb2, encode_jb2_djbz,
};

const MAX_SYMBOL_PIXELS: u64 = 1024 * 1024;

fn main() {
    let path = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "tests/corpus/pathogenic_bacteria_1896.djvu".to_string());
    let data = std::fs::read(&path).expect("read corpus");
    let doc = DjVuDocument::parse(&data).expect("parse corpus");
    eprintln!("[probe] {path}: {} pages", doc.page_count());

    let mut pages: Vec<Bitmap> = Vec::new();
    for i in 0..doc.page_count() {
        if let Ok(Some(bm)) = doc.page(i).and_then(|p| p.extract_mask()) {
            pages.push(bm);
        }
    }
    eprintln!("[probe] {} pages with masks", pages.len());

    let shared = cluster_shared_symbols_tunable(&pages, 2, 0);
    eprintln!("[probe] cluster -> {} shared symbols", shared.len());

    let mut over = Vec::new();
    let mut max_w = 0u32;
    let mut max_h = 0u32;
    let mut max_pix = 0u64;
    let mut total_pix: u64 = 0;
    for (i, sym) in shared.iter().enumerate() {
        let pix = (sym.width as u64) * (sym.height as u64);
        total_pix += pix;
        if sym.width > max_w {
            max_w = sym.width;
        }
        if sym.height > max_h {
            max_h = sym.height;
        }
        if pix > max_pix {
            max_pix = pix;
        }
        if pix > MAX_SYMBOL_PIXELS {
            over.push((i, sym.width, sym.height, pix));
        }
    }
    eprintln!(
        "[probe] max single-symbol w={max_w} h={max_h} pixels={max_pix} (cap={MAX_SYMBOL_PIXELS})"
    );
    eprintln!(
        "[probe] total symbol pixels = {total_pix} (cap MAX_TOTAL_SYMBOL_PIXELS = 64MP = {})",
        64u64 * 1024 * 1024
    );
    eprintln!("[probe] {} symbols exceed MAX_SYMBOL_PIXELS", over.len());
    for (i, w, h, p) in over.iter().take(20) {
        eprintln!("  shared[{i}] = {w}x{h} = {p} pixels");
    }

    // Now encode the shared dict standalone and try to decode it.
    let djbz = encode_jb2_djbz(&shared);
    eprintln!("[probe] encode_jb2_djbz -> {} bytes", djbz.len());
    match decode_dict(&djbz, None) {
        Ok(_) => eprintln!("[probe] decode_dict OK"),
        Err(e) => eprintln!("[probe] decode_dict FAILED: {e:?}"),
    }

    // Repro via the SHIPPED public API: encode_djvm_bundle_jb2(pages, 2).
    eprintln!("\n[probe] testing shipped encode_djvm_bundle_jb2(pages, 2)…");
    let bundle = encode_djvm_bundle_jb2(&pages, 2);
    eprintln!("[probe]   bundle = {} bytes", bundle.len());
    let bundle_doc = DjVuDocument::parse(&bundle).expect("bundle parse");
    let r = bundle_doc.page(0).and_then(|p| p.extract_mask());
    eprintln!("[probe]   page(0).extract_mask() = {:?}", r.as_ref().err());
}

