//! IW44 quality diagnostic for issue-driven investigations.
//!
//! Re-encodes existing BG44 backgrounds with a small set of diagnostic variants
//! and prints JSONL.  This example is intentionally not a benchmark harness:
//! it is for localizing whether quality loss is from chroma sampling, luma
//! quantization/slice budget, or another encoder stage.
//!
//! Usage:
//!   cargo run --release --features=std --example diagnose_iw44_quality -- \
//!     tests/corpus/watchmaker.djvu tests/corpus/conquete_paix.djvu

use std::path::Path;
use std::process::ExitCode;

use djvu_rs::{
    DjVuDocument, Pixmap,
    iw44_encode::{Iw44EncodeOptions, encode_iw44_color, encode_iw44_gray},
    iw44_new::Iw44Image,
};

#[derive(Clone, Copy)]
enum Variant {
    ModelCurrent,
    ModelInverse,
    Default,
    FullChroma,
    MoreSlices,
    GrayLumaOnly,
}

impl Variant {
    fn name(self) -> &'static str {
        match self {
            Variant::ModelCurrent => "model_current_ycbcr",
            Variant::ModelInverse => "model_inverse_ycbcr",
            Variant::Default => "default",
            Variant::FullChroma => "full_chroma",
            Variant::MoreSlices => "more_slices",
            Variant::GrayLumaOnly => "gray_luma_only",
        }
    }
}

#[derive(Debug)]
struct VariantResult {
    bytes: usize,
    psnr_luma_db: f64,
    psnr_rgb_db: f64,
}

fn luma(r: u8, g: u8, b: u8) -> f64 {
    0.299 * f64::from(r) + 0.587 * f64::from(g) + 0.114 * f64::from(b)
}

fn psnr_luma(a: &Pixmap, b: &Pixmap) -> f64 {
    assert_eq!(a.width, b.width);
    assert_eq!(a.height, b.height);
    let mut mse = 0.0f64;
    let mut n = 0usize;
    for (ra, rb) in a.data.chunks_exact(4).zip(b.data.chunks_exact(4)) {
        let d = luma(ra[0], ra[1], ra[2]) - luma(rb[0], rb[1], rb[2]);
        mse += d * d;
        n += 1;
    }
    psnr_from_mse(mse, n)
}

fn psnr_rgb(a: &Pixmap, b: &Pixmap) -> f64 {
    assert_eq!(a.width, b.width);
    assert_eq!(a.height, b.height);
    let mut mse = 0.0f64;
    let mut n = 0usize;
    for (ra, rb) in a.data.chunks_exact(4).zip(b.data.chunks_exact(4)) {
        for chan in 0..3 {
            let d = f64::from(ra[chan]) - f64::from(rb[chan]);
            mse += d * d;
            n += 1;
        }
    }
    psnr_from_mse(mse, n)
}

fn psnr_from_mse(sum_sq: f64, n: usize) -> f64 {
    if n == 0 {
        return f64::NAN;
    }
    let mse = sum_sq / n as f64;
    if mse == 0.0 {
        f64::INFINITY
    } else {
        10.0 * (255.0 * 255.0 / mse).log10()
    }
}

fn current_encoder_ycbcr(r: u8, g: u8, b: u8) -> (i32, i32, i32) {
    let r = i32::from(r);
    let g = i32::from(g);
    let b = i32::from(b);
    let y = (r + (g << 1) + b) / 4 - 128;
    let cb = b - g;
    let cr = r - g;
    (y.clamp(-128, 127), cb.clamp(-256, 255), cr.clamp(-256, 255))
}

fn inverse_compatible_ycbcr(r: u8, g: u8, b: u8) -> (i32, i32, i32) {
    let r = i32::from(r);
    let g = i32::from(g);
    let b = i32::from(b);
    let dr = r - g;
    let db = b - g;
    let cb = ((-2 * dr + 8 * db) as f64 / 15.0).round() as i32;
    let cr = ((8 * dr - db) as f64 / 15.0).round() as i32;
    let y = (g - 128) + ((cb as f64 / 4.0) + (cr as f64 / 2.0)).round() as i32;
    (y.clamp(-128, 127), cb.clamp(-128, 127), cr.clamp(-128, 127))
}

fn ycbcr_to_rgb(y: i32, cb: i32, cr: i32) -> (u8, u8, u8) {
    let t2 = cr + (cr >> 1);
    let t3 = y + 128 - (cb >> 2);
    (
        (y + 128 + t2).clamp(0, 255) as u8,
        (t3 - (cr >> 1)).clamp(0, 255) as u8,
        (t3 + (cb << 1)).clamp(0, 255) as u8,
    )
}

fn model_roundtrip(reference: &Pixmap, model: fn(u8, u8, u8) -> (i32, i32, i32)) -> Pixmap {
    let mut out = Pixmap::white(reference.width, reference.height);
    for y in 0..reference.height {
        for x in 0..reference.width {
            let (r, g, b) = reference.get_rgb(x, y);
            let (yy, cb, cr) = model(r, g, b);
            let (rr, gg, bb) = ycbcr_to_rgb(yy, cb, cr);
            out.set_rgb(x, y, rr, gg, bb);
        }
    }
    out
}

fn json_float(value: f64) -> String {
    if value.is_finite() {
        format!("{value:.3}")
    } else {
        "null".to_string()
    }
}

fn json_string(value: &str) -> String {
    serde_json::to_string(value).expect("string serialization cannot fail")
}

fn decode_bg44_chunks(chunks: &[&[u8]]) -> Option<Pixmap> {
    let mut img = Iw44Image::new();
    for chunk in chunks {
        img.decode_chunk(chunk).ok()?;
    }
    img.to_rgb().ok()
}

fn decode_bg44_owned(chunks: &[Vec<u8>]) -> Option<Pixmap> {
    let mut img = Iw44Image::new();
    for chunk in chunks {
        img.decode_chunk(chunk).ok()?;
    }
    img.to_rgb().ok()
}

fn encode_variant(reference: &Pixmap, variant: Variant) -> Option<VariantResult> {
    if matches!(variant, Variant::ModelCurrent | Variant::ModelInverse) {
        let decoded = match variant {
            Variant::ModelCurrent => model_roundtrip(reference, current_encoder_ycbcr),
            Variant::ModelInverse => model_roundtrip(reference, inverse_compatible_ycbcr),
            _ => unreachable!(),
        };
        return Some(VariantResult {
            bytes: 0,
            psnr_luma_db: psnr_luma(reference, &decoded),
            psnr_rgb_db: psnr_rgb(reference, &decoded),
        });
    }

    let chunks = match variant {
        Variant::ModelCurrent | Variant::ModelInverse => unreachable!(),
        Variant::Default => encode_iw44_color(reference, &Iw44EncodeOptions::default()),
        Variant::FullChroma => {
            let opts = Iw44EncodeOptions {
                chroma_half: false,
                ..Iw44EncodeOptions::default()
            };
            encode_iw44_color(reference, &opts)
        }
        Variant::MoreSlices => {
            let opts = Iw44EncodeOptions {
                total_slices: 200,
                slices_per_chunk: 20,
                ..Iw44EncodeOptions::default()
            };
            encode_iw44_color(reference, &opts)
        }
        Variant::GrayLumaOnly => {
            let gray = reference.to_gray8();
            let opts = Iw44EncodeOptions {
                total_slices: 200,
                slices_per_chunk: 20,
                ..Iw44EncodeOptions::default()
            };
            encode_iw44_gray(&gray, &opts)
        }
    };
    let bytes = chunks.iter().map(Vec::len).sum();
    let decoded = decode_bg44_owned(&chunks)?;
    Some(VariantResult {
        bytes,
        psnr_luma_db: psnr_luma(reference, &decoded),
        psnr_rgb_db: psnr_rgb(reference, &decoded),
    })
}

fn process_file(path: &Path) -> Result<usize, String> {
    let data = std::fs::read(path).map_err(|err| err.to_string())?;
    let doc = DjVuDocument::parse(&data).map_err(|err| err.to_string())?;
    let variants = [
        Variant::ModelCurrent,
        Variant::ModelInverse,
        Variant::Default,
        Variant::FullChroma,
        Variant::MoreSlices,
        Variant::GrayLumaOnly,
    ];

    let mut pages = 0usize;
    for page_idx in 0..doc.page_count() {
        let page = doc.page(page_idx).map_err(|err| err.to_string())?;
        let bg44_chunks = page.bg44_chunks();
        if bg44_chunks.is_empty() {
            continue;
        }
        let orig_bytes = bg44_chunks.iter().map(|chunk| chunk.len()).sum::<usize>();
        let Some(reference) = decode_bg44_chunks(&bg44_chunks) else {
            eprintln!(
                "skip {} page {}: original BG44 decode failed",
                path.display(),
                page_idx
            );
            continue;
        };

        for variant in variants {
            let Some(result) = encode_variant(&reference, variant) else {
                eprintln!(
                    "skip {} page {} variant {}: decode failed",
                    path.display(),
                    page_idx,
                    variant.name()
                );
                continue;
            };
            println!(
                "{{\"file\":{},\"page\":{},\"variant\":{},\
                 \"width\":{},\"height\":{},\"orig_bg44_bytes\":{},\
                 \"rs_bg44_bytes\":{},\"byte_ratio\":{:.3},\
                 \"psnr_luma_db\":{},\"psnr_rgb_db\":{}}}",
                json_string(&path.display().to_string()),
                page_idx,
                json_string(variant.name()),
                reference.width,
                reference.height,
                orig_bytes,
                result.bytes,
                result.bytes as f64 / orig_bytes.max(1) as f64,
                json_float(result.psnr_luma_db),
                json_float(result.psnr_rgb_db)
            );
        }
        pages += 1;
    }
    Ok(pages)
}

fn main() -> ExitCode {
    let args = std::env::args().skip(1).collect::<Vec<_>>();
    if args.is_empty() {
        eprintln!("usage: diagnose_iw44_quality <file.djvu> [<file2.djvu> ...]");
        return ExitCode::from(2);
    }

    let mut total = 0usize;
    for arg in args {
        match process_file(Path::new(&arg)) {
            Ok(pages) => total += pages,
            Err(err) => eprintln!("skip {arg}: {err}"),
        }
    }

    if total == 0 {
        eprintln!("no BG44 pages processed");
        return ExitCode::from(1);
    }
    ExitCode::SUCCESS
}

//! Differential testing harness against DjVuLibre's `ddjvu` (#192).
//!
//! For every page in each input file, renders the page with djvu-rs and with
//! `ddjvu` (subprocess) at the same target size, then compares the two RGBA
//! pixmaps with a per-pixel tolerance.
//!
//! Output: one JSON line per page (jsonl) + a stderr summary.
//!
//! Usage:
//!     cargo run --release --features=cli --example diff_djvulibre -- \
//!         [--width N] [--tolerance T] [--max-pages M] <file.djvu> [...]
//!
//!     --width N        target render width in px (default 1024). Height is
//!                      derived from page aspect ratio.
//!     --tolerance T    max allowed |Δ| per channel before a pixel counts
//!                      as a mismatch (default 4 — accommodates the small
//!                      rounding differences in IW44 wavelet reconstruction
//!                      between the two implementations).
//!     --max-pages M    cap pages compared per file (default 0 = unlimited).
//!
//! Notes:
//!  * `ddjvu` must be on `$PATH`. Brew: `brew install djvulibre`.
//!  * GPL/MIT cleanliness: the GPL `ddjvu` is invoked as an out-of-process
//!    binary; no GPL code is linked into this crate.
//!  * This is **Option B** from #192 — slow but trivially correct. CI-grade
//!    differential fuzzing (Option C: pre-rendered reference corpus + libfuzzer
//!    target) is a separate piece of work tracked on the issue.

// Names the deprecated, now-ignored `RenderOptions::scale` field (#377); allowed
// so this harness keeps building while the back-compat field exists.
#![allow(deprecated)]

use std::io::Read;
use std::path::Path;
use std::process::{Command, ExitCode};

use djvu_rs::{
    DjVuDocument, Pixmap,
    djvu_render::{RenderOptions, render_pixmap},
};

#[derive(Clone, Copy, Debug, Default)]
struct PageDiff {
    page: usize,
    width: u32,
    height: u32,
    total_px: u64,
    mismatched_px: u64,
    max_abs_diff: u8,
    mean_abs_diff: f64,
}

fn parse_ppm(data: &[u8]) -> Option<(u32, u32, &[u8])> {
    // Minimal P6 PPM parser (binary). Header: "P6\n<W> <H>\n<MAX>\n<bytes>"
    // Tolerates extra whitespace and `# ...` comments per the format spec.
    fn skip_ws_and_comments(d: &[u8], i: &mut usize) {
        while *i < d.len() {
            match d[*i] {
                b' ' | b'\t' | b'\n' | b'\r' => *i += 1,
                b'#' => {
                    while *i < d.len() && d[*i] != b'\n' {
                        *i += 1;
                    }
                }
                _ => break,
            }
        }
    }
    fn read_token<'a>(d: &'a [u8], i: &mut usize) -> Option<&'a [u8]> {
        skip_ws_and_comments(d, i);
        let start = *i;
        while *i < d.len() && !matches!(d[*i], b' ' | b'\t' | b'\n' | b'\r') {
            *i += 1;
        }
        if *i == start {
            None
        } else {
            Some(&d[start..*i])
        }
    }

    if data.len() < 2 || &data[..2] != b"P6" {
        return None;
    }
    let mut i: usize = 2;
    let w: u32 = std::str::from_utf8(read_token(data, &mut i)?)
        .ok()?
        .parse()
        .ok()?;
    let h: u32 = std::str::from_utf8(read_token(data, &mut i)?)
        .ok()?
        .parse()
        .ok()?;
    let max: u32 = std::str::from_utf8(read_token(data, &mut i)?)
        .ok()?
        .parse()
        .ok()?;
    if max != 255 {
        return None;
    }
    // Exactly one whitespace byte separates the maxval from the binary data.
    if i >= data.len() {
        return None;
    }
    i += 1;
    let needed = (w as usize) * (h as usize) * 3;
    if data.len() < i + needed {
        return None;
    }
    Some((w, h, &data[i..i + needed]))
}

/// Compare a djvu-rs RGBA pixmap with ddjvu's RGB PPM bytes at matching size.
fn compare(rs: &Pixmap, libre_w: u32, libre_h: u32, libre_rgb: &[u8], tolerance: u8) -> PageDiff {
    assert_eq!(rs.width, libre_w);
    assert_eq!(rs.height, libre_h);
    let n = (rs.width as u64) * (rs.height as u64);
    let mut mismatched = 0u64;
    let mut max_abs = 0u8;
    let mut sum_abs: u64 = 0;
    for i in 0..(n as usize) {
        let r = rs.data[i * 4];
        let g = rs.data[i * 4 + 1];
        let b = rs.data[i * 4 + 2];
        let lr = libre_rgb[i * 3];
        let lg = libre_rgb[i * 3 + 1];
        let lb = libre_rgb[i * 3 + 2];
        let dr = r.abs_diff(lr);
        let dg = g.abs_diff(lg);
        let db = b.abs_diff(lb);
        let m = dr.max(dg).max(db);
        if m > tolerance {
            mismatched += 1;
        }
        if m > max_abs {
            max_abs = m;
        }
        sum_abs += dr as u64 + dg as u64 + db as u64;
    }
    PageDiff {
        page: 0,
        width: rs.width,
        height: rs.height,
        total_px: n,
        mismatched_px: mismatched,
        max_abs_diff: max_abs,
        mean_abs_diff: sum_abs as f64 / (n as f64 * 3.0),
    }
}

fn render_ddjvu(path: &Path, page_idx: usize, w: u32, h: u32) -> Option<(u32, u32, Vec<u8>)> {
    let out = tempfile::NamedTempFile::new().ok()?;
    let out_path = out.path().to_path_buf();
    let status = Command::new("ddjvu")
        .arg("-format=ppm")
        .arg(format!("-page={}", page_idx + 1))
        .arg(format!("-size={w}x{h}"))
        .arg("-aspect=no")
        .arg(path)
        .arg(&out_path)
        .status()
        .ok()?;
    if !status.success() {
        return None;
    }
    let mut data = Vec::new();
    std::fs::File::open(&out_path)
        .ok()?
        .read_to_end(&mut data)
        .ok()?;
    let (pw, ph, rgb) = parse_ppm(&data)?;
    Some((pw, ph, rgb.to_vec()))
}

fn process_file(path: &Path, target_w: u32, tolerance: u8, max_pages: usize) -> Vec<PageDiff> {
    let bytes = match std::fs::read(path) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("skip {}: {}", path.display(), e);
            return vec![];
        }
    };
    let doc = match DjVuDocument::parse(&bytes) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("skip {}: {}", path.display(), e);
            return vec![];
        }
    };
    let pc = doc.page_count();
    let cap = if max_pages == 0 {
        pc
    } else {
        pc.min(max_pages)
    };

    let mut out = Vec::new();
    for page_idx in 0..cap {
        let page = match doc.page(page_idx) {
            Ok(p) => p,
            Err(_) => continue,
        };
        let pw = page.width() as u32;
        let ph = page.height() as u32;
        if pw == 0 || ph == 0 {
            continue;
        }
        let render_w = target_w.min(pw);
        let render_h = ((ph as u64 * render_w as u64) / pw as u64).max(1) as u32;

        let opts = RenderOptions {
            width: render_w,
            height: render_h,
            scale: render_w as f32 / pw as f32,
            ..Default::default()
        };
        let rs_pix = match render_pixmap(page, &opts) {
            Ok(p) => p,
            Err(e) => {
                eprintln!(
                    "djvu-rs render failed at {}#p{page_idx}: {e}",
                    path.display()
                );
                continue;
            }
        };

        let (libre_w, libre_h, libre_rgb) = match render_ddjvu(path, page_idx, render_w, render_h) {
            Some(t) => t,
            None => {
                eprintln!("ddjvu render failed at {}#p{page_idx}", path.display());
                continue;
            }
        };
        if libre_w != rs_pix.width || libre_h != rs_pix.height {
            eprintln!(
                "size mismatch at {}#p{page_idx}: rs {}x{} vs libre {}x{}",
                path.display(),
                rs_pix.width,
                rs_pix.height,
                libre_w,
                libre_h
            );
            continue;
        }

        let mut d = compare(&rs_pix, libre_w, libre_h, &libre_rgb, tolerance);
        d.page = page_idx;
        out.push(d);
    }
    out
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let mut target_w: u32 = 1024;
    let mut tolerance: u8 = 4;
    let mut max_pages: usize = 0;
    let mut files: Vec<String> = Vec::new();
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--width" => {
                i += 1;
                target_w = args.get(i).and_then(|s| s.parse().ok()).unwrap_or(1024);
            }
            "--tolerance" => {
                i += 1;
                tolerance = args.get(i).and_then(|s| s.parse().ok()).unwrap_or(4);
            }
            "--max-pages" => {
                i += 1;
                max_pages = args.get(i).and_then(|s| s.parse().ok()).unwrap_or(0);
            }
            "-h" | "--help" => {
                eprintln!(
                    "usage: diff_djvulibre [--width N] [--tolerance T] [--max-pages M] <file.djvu> [...]"
                );
                return ExitCode::from(2);
            }
            other => files.push(other.to_string()),
        }
        i += 1;
    }
    if files.is_empty() {
        eprintln!(
            "usage: diff_djvulibre [--width N] [--tolerance T] [--max-pages M] <file.djvu> [...]"
        );
        return ExitCode::from(2);
    }

    let mut total_pages = 0u64;
    let mut total_px = 0u128;
    let mut total_mismatched = 0u128;
    let mut max_abs_global = 0u8;
    let mut max_mismatch_pct: f64 = 0.0;
    let mut worst_page: Option<(String, usize, f64)> = None;

    for arg in &files {
        let path = Path::new(arg);
        for d in process_file(path, target_w, tolerance, max_pages) {
            let pct = (d.mismatched_px as f64) / (d.total_px as f64) * 100.0;
            println!(
                "{{\"file\":\"{}\",\"page\":{},\"width\":{},\"height\":{},\
                 \"total_px\":{},\"mismatched_px\":{},\"mismatch_pct\":{:.4},\
                 \"max_abs_diff\":{},\"mean_abs_diff\":{:.3}}}",
                path.display(),
                d.page,
                d.width,
                d.height,
                d.total_px,
                d.mismatched_px,
                pct,
                d.max_abs_diff,
                d.mean_abs_diff
            );
            total_pages += 1;
            total_px += d.total_px as u128;
            total_mismatched += d.mismatched_px as u128;
            if d.max_abs_diff > max_abs_global {
                max_abs_global = d.max_abs_diff;
            }
            if pct > max_mismatch_pct {
                max_mismatch_pct = pct;
                worst_page = Some((arg.clone(), d.page, pct));
            }
        }
    }

    if total_pages == 0 {
        eprintln!("no pages compared");
        return ExitCode::from(1);
    }

    eprintln!();
    eprintln!("=== diff vs DjVuLibre ddjvu ===");
    eprintln!("pages compared:       {total_pages}");
    eprintln!("total pixels:         {total_px}");
    eprintln!(
        "mismatched (>tol={}): {total_mismatched}  ({:.4}% of total)",
        tolerance,
        (total_mismatched as f64) / (total_px as f64) * 100.0
    );
    eprintln!("max |Δ| any channel:  {max_abs_global}");
    if let Some((f, p, pct)) = worst_page {
        eprintln!("worst page:           {f} #p{p} ({pct:.4}% mismatched)");
    }

    ExitCode::SUCCESS
}

//! Multi-page shared-Djbz quality benchmark (#194 Phase 2).
//!
//! For each multi-page DjVu input, extracts every page's bilevel mask, then
//! compares three encoder modes:
//!   1. **Original** — sum of source Sjbz chunks (typically `cjb2`).
//!   2. **Independent** — `encode_jb2_dict(page)` per page, summed.
//!   3. **Bundled** — `encode_djvm_bundle_jb2(pages, threshold)` total bytes
//!      (Djbz + per-page Sjbz, IFF/DIRM overhead included).
//!
//! Win = bundled / independent < 1.0.
//!
//! On 517-page `pathogenic_bacteria_1896.djvu` (real cjb2 scan corpus) the
//! shipped byte-exact clustering (`--diff-fraction 0`) gives bundle = 87.0%
//! of independent (−13.0%); 1%/2% Hamming clustering matches it within 0.05%;
//! 3% introduces decode mismatches under rec-6 refinement. See CLAUDE.md
//! "Multi-page shared Djbz dictionary, Phase 2" for the full investigation.
//!
//! Usage:
//!     cargo run --release --example encode_quality_djbz -- <file.djvu> [<file2.djvu> ...]
//!         [--threshold N]   # default 2 (default for encode_djvm_bundle_jb2)
//!
//! Output: per-file JSON line on stdout + summary table on stderr.
//!
//! Verifies bundle round-trip (every page decodes pixel-exact).

use std::path::Path;
use std::process::ExitCode;

use djvu_rs::jb2_encode::analyze_jb2_cross_size_refinement;
use djvu_rs::{
    Bitmap, DjVuDocument,
    jb2_encode::{
        CcStats, analyze_jb2_cc_stats, cluster_shared_symbols_tunable,
        encode_djvm_bundle_jb2_with_shared, encode_jb2_dict, encode_jb2_dict_with_shared,
        encode_jb2_djbz,
    },
};

struct FileResult {
    file: String,
    pages: usize,
    width_h_avg: (u32, u32),
    orig_total: usize,
    indep_total: usize,
    bundle_total: usize,
    roundtrip_ok: bool,
    #[allow(dead_code)]
    diff_fraction: u32,
}

fn collect_pages(path: &Path) -> Option<(Vec<Bitmap>, usize, (u32, u32))> {
    let data = std::fs::read(path).ok()?;
    let doc = DjVuDocument::parse(&data).ok()?;
    let mut pages = Vec::new();
    let mut orig_total = 0usize;
    let (mut sw, mut sh, mut n) = (0u64, 0u64, 0u64);
    for i in 0..doc.page_count() {
        let p = match doc.page(i) {
            Ok(p) => p,
            Err(_) => continue,
        };
        if let Some(s) = p.raw_chunk(b"Sjbz") {
            orig_total += s.len();
        }
        let bm = match p.extract_mask() {
            Ok(Some(b)) => b,
            _ => continue,
        };
        sw += bm.width as u64;
        sh += bm.height as u64;
        n += 1;
        pages.push(bm);
    }
    if pages.is_empty() {
        return None;
    }
    let avg = ((sw / n) as u32, (sh / n) as u32);
    Some((pages, orig_total, avg))
}

/// Aggregate per-page CC stats across all pages of a bundle.
fn aggregate_cc_stats(pages: &[Bitmap], shared: &[Bitmap]) -> CcStats {
    let mut agg = CcStats::default();
    for p in pages {
        let s = analyze_jb2_cc_stats(p, shared);
        agg.total_ccs += s.total_ccs;
        agg.rec_7_exact += s.rec_7_exact;
        agg.rec_6_refine_shared += s.rec_6_refine_shared;
        agg.rec_6_refine_local += s.rec_6_refine_local;
        agg.rec_1_new += s.rec_1_new;
        agg.pixels_rec_1 += s.pixels_rec_1;
        agg.pixels_rec_6 += s.pixels_rec_6;
        agg.pixels_rec_7 += s.pixels_rec_7;
        agg.rec_6_hamming.extend(s.rec_6_hamming);
    }
    agg
}

/// Print a fixed-bin Hamming-distance histogram for rec-6 emissions.
/// Bins are in % of pixel-count (Hamming / pixel_count × 100), with the
/// caveat that we don't have per-CC pixel context in the aggregate, so
/// we report by absolute Hamming distance bucketed into power-of-two bins.
fn print_hamming_histogram(hamming: &[u32]) {
    if hamming.is_empty() {
        eprintln!("  rec-6 Hamming histogram: (no rec-6 emissions)");
        return;
    }
    let bins: [(u32, u32, &str); 7] = [
        (0, 0, "=0"),
        (1, 4, "1-4"),
        (5, 16, "5-16"),
        (17, 64, "17-64"),
        (65, 256, "65-256"),
        (257, 1024, "257-1024"),
        (1025, u32::MAX, ">1024"),
    ];
    let total = hamming.len();
    eprintln!("  rec-6 Hamming histogram ({} matches):", total);
    for (lo, hi, label) in bins {
        let n = hamming.iter().filter(|&&h| h >= lo && h <= hi).count();
        let pct = n as f64 / total as f64 * 100.0;
        eprintln!("    {:>10}: {:>6} ({:>5.1}%)", label, n, pct);
    }
}

fn process_file(
    path: &Path,
    threshold: usize,
    diff_fraction: u32,
    cc_stats: bool,
    cross_size_stats: bool,
) -> Option<FileResult> {
    let (pages, orig_total, avg) = match collect_pages(path) {
        Some(t) => t,
        None => {
            eprintln!("skip {}: no JB2 pages", path.display());
            return None;
        }
    };

    let indep_total: usize = pages
        .iter()
        .map(|p: &Bitmap| encode_jb2_dict(p).len())
        .sum();

    // Build the bundle with a tunable cluster Hamming threshold so we can
    // sweep different fractions independently of the shipped default.
    let shared = cluster_shared_symbols_tunable(&pages, threshold, diff_fraction);
    let bundle = encode_djvm_bundle_jb2_with_shared(&pages, &shared);
    let bundle_total = bundle.len();

    // Diagnostic breakdown: how big is the shared dict, vs per-page Sjbz?
    let djbz_bytes = if shared.is_empty() {
        0
    } else {
        encode_jb2_djbz(&shared).len()
    };
    let sjbz_total: usize = pages
        .iter()
        .map(|p| encode_jb2_dict_with_shared(p, &shared).len())
        .sum();
    eprintln!(
        "  {}: diff={}% shared_syms={} djbz={}B sjbz_total={}B (jb2={}B, container_overhead={}B)",
        path.display(),
        diff_fraction,
        shared.len(),
        djbz_bytes,
        sjbz_total,
        djbz_bytes + sjbz_total,
        bundle_total.saturating_sub(djbz_bytes + sjbz_total),
    );

    if cc_stats {
        let agg = aggregate_cc_stats(&pages, &shared);
        eprintln!(
            "  CC accounting: total={} rec-1={} ({:.1}%) rec-6_shared={} ({:.1}%) \
             rec-6_local={} ({:.1}%) rec-7_exact={} ({:.1}%)",
            agg.total_ccs,
            agg.rec_1_new,
            agg.rec_1_new as f64 / agg.total_ccs.max(1) as f64 * 100.0,
            agg.rec_6_refine_shared,
            agg.rec_6_refine_shared as f64 / agg.total_ccs.max(1) as f64 * 100.0,
            agg.rec_6_refine_local,
            agg.rec_6_refine_local as f64 / agg.total_ccs.max(1) as f64 * 100.0,
            agg.rec_7_exact,
            agg.rec_7_exact as f64 / agg.total_ccs.max(1) as f64 * 100.0,
        );
        eprintln!(
            "  pixel volume: rec-1={} px  rec-6={} px  rec-7={} px",
            agg.pixels_rec_1, agg.pixels_rec_6, agg.pixels_rec_7,
        );
        print_hamming_histogram(&agg.rec_6_hamming);
    }
    if cross_size_stats {
        let mut total = djvu_rs::jb2_encode::CrossSizeRefinementStats::default();
        for p in &pages {
            let s = analyze_jb2_cross_size_refinement(p, &shared, 2, 0.05);
            total.total_ccs += s.total_ccs;
            total.fresh_ccs += s.fresh_ccs;
            total.eligible_fresh_ccs += s.eligible_fresh_ccs;
            total.candidate_ccs += s.candidate_ccs;
            total.near_matches += s.near_matches;
            total.near_match_pixels += s.near_match_pixels;
            total.best_hamming.extend(s.best_hamming);
            total.estimated_rec1_bytes += s.estimated_rec1_bytes;
            total.estimated_cross_size_rec6_bytes += s.estimated_cross_size_rec6_bytes;
            total.estimated_byte_delta += s.estimated_byte_delta;
        }
        let median = if total.best_hamming.is_empty() {
            0
        } else {
            total.best_hamming.sort_unstable();
            total.best_hamming[total.best_hamming.len() / 2]
        };
        eprintln!(
            "  cross-size probe: fresh={} eligible={} candidates={} near_5pct={} ({:.2}%) near_pixels={} median_best_hamming={}",
            total.fresh_ccs,
            total.eligible_fresh_ccs,
            total.candidate_ccs,
            total.near_matches,
            total.near_matches as f64 / total.eligible_fresh_ccs.max(1) as f64 * 100.0,
            total.near_match_pixels,
            median,
        );
        eprintln!(
            "  cross-size byte estimate: current_rec1={}B hypothetical_rec6={}B delta={}B ({:.2}% of independent)",
            total.estimated_rec1_bytes,
            total.estimated_cross_size_rec6_bytes,
            total.estimated_byte_delta,
            total.estimated_byte_delta as f64 / indep_total.max(1) as f64 * 100.0,
        );
        eprintln!(
            "  cross-size semantics: hypothetical rec-6 would be lossless if emitted with a full refinement bitmap; this probe does not emit bytes and uses nearest-neighbor scaled Hamming only for candidate selection/cost estimation",
        );
    }

    // Verify round-trip — every page must decode pixel-exact.
    let roundtrip_ok = match DjVuDocument::parse(&bundle) {
        Ok(doc) if doc.page_count() == pages.len() => {
            let mut all_ok = true;
            for (i, page) in pages.iter().enumerate() {
                let decoded = match doc.page(i).and_then(|p| p.extract_mask()) {
                    Ok(Some(d)) => d,
                    Ok(None) => {
                        eprintln!("  MISMATCH page {i}: extract_mask returned None (no Sjbz?)");
                        all_ok = false;
                        continue;
                    }
                    Err(e) => {
                        eprintln!("  MISMATCH page {i}: extract_mask error: {e:?}");
                        all_ok = false;
                        continue;
                    }
                };
                let dim_ok = decoded.width == page.width && decoded.height == page.height;
                let diff_px = if dim_ok {
                    let mut diff = 0u32;
                    for y in 0..page.height {
                        for x in 0..page.width {
                            if page.get(x, y) != decoded.get(x, y) {
                                diff += 1;
                            }
                        }
                    }
                    diff
                } else {
                    0
                };
                if !dim_ok || diff_px != 0 {
                    eprintln!(
                        "  MISMATCH page {i}: {}×{} → {}×{} diff_px={}",
                        page.width, page.height, decoded.width, decoded.height, diff_px
                    );
                    all_ok = false;
                }
            }
            all_ok
        }
        Ok(doc) => {
            eprintln!(
                "  page_count mismatch: bundle={} expected={}",
                doc.page_count(),
                pages.len()
            );
            false
        }
        Err(e) => {
            eprintln!("  DjVuDocument::parse failed: {e:?}");
            false
        }
    };

    Some(FileResult {
        file: path.display().to_string(),
        pages: pages.len(),
        width_h_avg: avg,
        orig_total,
        indep_total,
        bundle_total,
        roundtrip_ok,
        diff_fraction,
    })
}

fn main() -> ExitCode {
    let mut threshold = 2usize;
    // Default 0 = byte-exact, the shipped clustering. Higher values opt
    // into Hamming clustering for experimentation.
    let mut diff_fraction: u32 = 0;
    let mut cc_stats = false;
    let mut cross_size_stats = false;
    let mut files: Vec<String> = Vec::new();
    let mut args = std::env::args().skip(1);
    while let Some(a) = args.next() {
        if a == "--threshold" {
            threshold = args
                .next()
                .and_then(|v| v.parse().ok())
                .unwrap_or(threshold);
        } else if a == "--diff-fraction" {
            diff_fraction = args
                .next()
                .and_then(|v| v.parse().ok())
                .unwrap_or(diff_fraction);
        } else if a == "--cc-stats" {
            cc_stats = true;
        } else if a == "--cross-size-stats" {
            cross_size_stats = true;
        } else {
            files.push(a);
        }
    }

    if files.is_empty() {
        eprintln!(
            "usage: encode_quality_djbz [--threshold N] [--diff-fraction P] [--cc-stats] [--cross-size-stats] <file.djvu> [...]\n\
             \n\
             Encodes every multi-page input via encode_djvm_bundle_jb2 and\n\
             reports total bytes vs. independent per-page dict + original Sjbz.\n\
             \n\
             --threshold N      promote glyph clusters that span >= N pages (default 2)\n\
             --diff-fraction P  Hamming distance allowance, percent of pixels (0..=10, default 0 = byte-exact)\n\
             --cc-stats         print per-CC record-type accounting + Hamming histogram (#194 Phase 2.5)\n\
             --cross-size-stats print experiment-only cross-size refinement headroom (#283)"
        );
        return ExitCode::from(2);
    }

    let mut all = Vec::new();
    for f in &files {
        if let Some(r) = process_file(
            Path::new(f),
            threshold,
            diff_fraction,
            cc_stats,
            cross_size_stats,
        ) {
            all.push(r);
        }
    }

    if all.is_empty() {
        eprintln!("no files processed");
        return ExitCode::from(1);
    }

    for r in &all {
        println!(
            "{{\"file\":\"{}\",\"pages\":{},\"avg_w\":{},\"avg_h\":{},\
             \"orig_bytes\":{},\"indep_bytes\":{},\"bundle_bytes\":{},\
             \"bundle_vs_indep\":{:.4},\"bundle_vs_orig\":{:.4},\
             \"threshold\":{},\"roundtrip_ok\":{}}}",
            r.file,
            r.pages,
            r.width_h_avg.0,
            r.width_h_avg.1,
            r.orig_total,
            r.indep_total,
            r.bundle_total,
            r.bundle_total as f64 / r.indep_total.max(1) as f64,
            r.bundle_total as f64 / r.orig_total.max(1) as f64,
            threshold,
            r.roundtrip_ok,
        );
    }

    let total_pages: usize = all.iter().map(|r| r.pages).sum();
    let total_orig: usize = all.iter().map(|r| r.orig_total).sum();
    let total_indep: usize = all.iter().map(|r| r.indep_total).sum();
    let total_bundle: usize = all.iter().map(|r| r.bundle_total).sum();
    let any_rt_fail = all.iter().any(|r| !r.roundtrip_ok);

    eprintln!();
    eprintln!(
        "=== shared-Djbz quality summary (threshold={}) ===",
        threshold
    );
    eprintln!("files: {}   pages: {}", all.len(), total_pages);
    eprintln!();
    eprintln!("{:<10} {:>14} {:>10}", "mode", "bytes", "vs orig");
    eprintln!(
        "{:<10} {:>14} {:>10}",
        "original",
        total_orig,
        format!("{:.3}×", 1.0)
    );
    eprintln!(
        "{:<10} {:>14} {:>10}",
        "independent",
        total_indep,
        format!("{:.3}×", total_indep as f64 / total_orig.max(1) as f64),
    );
    eprintln!(
        "{:<10} {:>14} {:>10}",
        "bundled",
        total_bundle,
        format!("{:.3}×", total_bundle as f64 / total_orig.max(1) as f64),
    );
    eprintln!();
    eprintln!(
        "shared-Djbz win (bundle/independent): {:.3}×  ({:+.1}%)",
        total_bundle as f64 / total_indep.max(1) as f64,
        (total_bundle as f64 / total_indep.max(1) as f64 - 1.0) * 100.0,
    );
    eprintln!();
    if any_rt_fail {
        eprintln!("⚠ round-trip FAILED on at least one file");
        return ExitCode::from(1);
    }
    eprintln!("✓ all bundle round-trips pixel-exact");
    ExitCode::SUCCESS
}

//! IW44 encoder quality benchmark — re-encodes the BG44 background of every
//! page in the supplied DjVu file(s), then measures PSNR (luminance) of the
//! re-decoded pixmap against djvu-rs's own decode of the original BG44.
//!
//! Output: one JSON line per page (jsonl), plus a final summary on stderr.
//!
//! Usage:
//!     cargo run --release --features=std --example encode_quality_iw44 -- <file.djvu> [...]

use std::path::Path;
use std::process::ExitCode;

use djvu_rs::{
    DjVuDocument, Pixmap,
    iw44_encode::{Iw44EncodeOptions, encode_iw44_color},
    iw44_new::Iw44Image,
};

#[derive(Clone, Copy, Debug)]
struct PageResult {
    page: usize,
    width: u32,
    height: u32,
    orig_bg44_bytes: usize,
    rs_bg44_bytes: usize,
    psnr_db: f64,
}

/// PSNR of `b` against reference `a` over a luminance channel.
/// Uses ITU-R BT.601 luma coefficients on RGBA8 pixmaps.
fn psnr_rgba(a: &Pixmap, b: &Pixmap) -> f64 {
    assert_eq!(a.width, b.width);
    assert_eq!(a.height, b.height);
    let n = (a.width as usize) * (a.height as usize);
    let mut mse = 0.0f64;
    for i in 0..n {
        let off = i * 4;
        let ay = 0.299 * a.data[off] as f64
            + 0.587 * a.data[off + 1] as f64
            + 0.114 * a.data[off + 2] as f64;
        let by = 0.299 * b.data[off] as f64
            + 0.587 * b.data[off + 1] as f64
            + 0.114 * b.data[off + 2] as f64;
        let d = ay - by;
        mse += d * d;
    }
    mse /= n as f64;
    if mse == 0.0 {
        return f64::INFINITY;
    }
    10.0 * (255.0 * 255.0 / mse).log10()
}

/// Decode an entire BG44 chunk stream into a Pixmap.
fn decode_bg44_chunks(chunks: &[&[u8]]) -> Option<Pixmap> {
    let mut img = Iw44Image::new();
    for c in chunks {
        img.decode_chunk(c).ok()?;
    }
    img.to_rgb().ok()
}

/// Same, for `Vec<Vec<u8>>` (encoder output).
fn decode_bg44_owned(chunks: &[Vec<u8>]) -> Option<Pixmap> {
    let mut img = Iw44Image::new();
    for c in chunks {
        img.decode_chunk(c).ok()?;
    }
    img.to_rgb().ok()
}

fn process_file(path: &Path) -> Vec<PageResult> {
    let data = match std::fs::read(path) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("skip {}: {}", path.display(), e);
            return vec![];
        }
    };
    let doc = match DjVuDocument::parse(&data) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("skip {}: parse failed: {}", path.display(), e);
            return vec![];
        }
    };

    let mut out = Vec::new();
    for page_idx in 0..doc.page_count() {
        let page = match doc.page(page_idx) {
            Ok(p) => p,
            Err(_) => continue,
        };
        let bg44_chunks: Vec<&[u8]> = page.bg44_chunks();
        if bg44_chunks.is_empty() {
            continue;
        }

        let orig_bytes: usize = bg44_chunks.iter().map(|d| d.len()).sum();
        let orig_pixmap = match decode_bg44_chunks(&bg44_chunks) {
            Some(p) => p,
            None => continue,
        };

        // Re-encode with the same chunking strategy as DjVuLibre's c44 default
        // (10 slices/chunk × 10 chunks = 100 slices total).
        let opts = Iw44EncodeOptions::default();
        let rs_chunks = encode_iw44_color(&orig_pixmap, &opts);
        let rs_bytes: usize = rs_chunks.iter().map(|v| v.len()).sum();

        let rs_pixmap = match decode_bg44_owned(&rs_chunks) {
            Some(p) => p,
            None => continue,
        };
        let psnr = psnr_rgba(&orig_pixmap, &rs_pixmap);

        out.push(PageResult {
            page: page_idx,
            width: orig_pixmap.width,
            height: orig_pixmap.height,
            orig_bg44_bytes: orig_bytes,
            rs_bg44_bytes: rs_bytes,
            psnr_db: psnr,
        });
    }
    out
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.is_empty() {
        eprintln!(
            "usage: encode_quality_iw44 <file.djvu> [<file2.djvu> ...]\n\
             \n\
             Re-encodes every BG44 background and measures PSNR vs djvu-rs's\n\
             decode of the original BG44 (the encoder is the unit under test;\n\
             the original decode is the reference)."
        );
        return ExitCode::from(2);
    }

    let mut total_orig = 0usize;
    let mut total_rs = 0usize;
    let mut total_pages = 0usize;
    let mut psnr_sum = 0.0f64;
    let mut psnr_min = f64::INFINITY;

    for arg in &args {
        let path = Path::new(arg);
        for r in process_file(path) {
            println!(
                "{{\"file\":\"{}\",\"page\":{},\"width\":{},\"height\":{},\
                 \"orig_bg44_bytes\":{},\"rs_bg44_bytes\":{},\"psnr_db\":{:.3}}}",
                path.display(),
                r.page,
                r.width,
                r.height,
                r.orig_bg44_bytes,
                r.rs_bg44_bytes,
                r.psnr_db
            );
            total_orig += r.orig_bg44_bytes;
            total_rs += r.rs_bg44_bytes;
            total_pages += 1;
            if r.psnr_db.is_finite() {
                psnr_sum += r.psnr_db;
                if r.psnr_db < psnr_min {
                    psnr_min = r.psnr_db;
                }
            }
        }
    }

    if total_pages == 0 {
        eprintln!("no IW44/BG44 pages processed");
        return ExitCode::from(1);
    }

    eprintln!();
    eprintln!("=== IW44 encoder quality summary ===");
    eprintln!("pages:          {}", total_pages);
    eprintln!("orig BG44 size: {:>10} bytes", total_orig);
    eprintln!(
        "rs   BG44 size: {:>10} bytes  ({:.3}× orig)",
        total_rs,
        total_rs as f64 / total_orig.max(1) as f64
    );
    eprintln!(
        "PSNR (luma):    avg {:.2} dB,  min {:.2} dB",
        psnr_sum / total_pages as f64,
        psnr_min
    );

    ExitCode::SUCCESS
}

//! JB2 encoder quality benchmark — compares djvu-rs re-encoded Sjbz payload
//! size against the original Sjbz chunk in a DjVu file (typically produced
//! by `cjb2` from DjVuLibre).
//!
//! Also verifies lossless round-trip: the re-encoded stream must decode to
//! the exact same `Bitmap` as the original.
//!
//! Usage:
//!     cargo run --release --example encode_quality_jb2 -- <file.djvu> [<file2.djvu> ...]
//!
//! Output: one JSON line per page (jsonl), plus a final summary table on stderr.
//!
//! Fields per page:
//!   file            — path of the source DjVu
//!   page            — 0-based page index
//!   width, height   — bitmap dimensions
//!   orig_sjbz_bytes — original Sjbz payload size
//!   rs_sjbz_bytes   — djvu-rs re-encoded Sjbz payload size
//!   bpp_orig        — bits per pixel of the original
//!   bpp_rs          — bits per pixel of the re-encoded
//!   size_ratio      — rs_sjbz_bytes / orig_sjbz_bytes (>1.0 means djvu-rs worse)
//!   roundtrip_ok    — re-encoded decodes to the same bitmap

use std::path::Path;
use std::process::ExitCode;

use djvu_rs::{
    Bitmap, DjVuDocument, jb2,
    jb2_encode::{Jb2EncodeOptions, encode_jb2, encode_jb2_dict, encode_jb2_dict_with_options},
};

#[derive(Copy, Clone, Debug)]
enum RoundtripStatus {
    Ok,
    Mismatch,
    /// Decoder rejected the re-encoded stream — see issue #198
    /// (encoder emits whole image as one type-3 symbol > MAX_SYMBOL_PIXELS).
    DecodeError,
}

impl RoundtripStatus {
    fn as_str(&self) -> &'static str {
        match self {
            RoundtripStatus::Ok => "ok",
            RoundtripStatus::Mismatch => "mismatch",
            RoundtripStatus::DecodeError => "decode_error",
        }
    }
}

struct PageResult {
    file: String,
    page: usize,
    width: u32,
    height: u32,
    orig_sjbz_bytes: usize,
    rs_sjbz_bytes: usize,
    rs_dict_sjbz_bytes: usize,
    rs_lossy_sjbz_bytes: usize,
    /// Reconstruction-error pixel count for lossy mode (Hamming between
    /// the original page bitmap and the lossy decode). 0 = lossless or
    /// no near-duplicates fired the substitution.
    lossy_hamming: u64,
    roundtrip: RoundtripStatus,
    roundtrip_dict: RoundtripStatus,
}

/// Pixel-wise Hamming distance between two same-size bitmaps. Used to
/// quantify lossy reconstruction error vs the original.
fn bitmap_hamming(a: &Bitmap, b: &Bitmap) -> u64 {
    if a.width != b.width || a.height != b.height || a.data.len() != b.data.len() {
        return u64::MAX;
    }
    let mut total: u64 = 0;
    for (x, y) in a.data.iter().zip(b.data.iter()) {
        total += (x ^ y).count_ones() as u64;
    }
    total
}

fn process_file(path: &Path, lossy_threshold: f32) -> Vec<PageResult> {
    let data = match std::fs::read(path) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("skip {}: {}", path.display(), e);
            return vec![];
        }
    };
    let doc = match DjVuDocument::parse(&data) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("skip {}: parse failed: {}", path.display(), e);
            return vec![];
        }
    };

    let mut out = Vec::new();
    for page_idx in 0..doc.page_count() {
        let page = match doc.page(page_idx) {
            Ok(p) => p,
            Err(_) => continue,
        };
        let orig_sjbz = match page.raw_chunk(b"Sjbz") {
            Some(s) => s,
            None => continue,
        };
        let bitmap = match page.extract_mask() {
            Ok(Some(b)) => b,
            _ => continue,
        };

        let rs_encoded = encode_jb2(&bitmap);
        let rs_dict_encoded = encode_jb2_dict(&bitmap);
        // `..Default::default()` is needless without the `experimental` feature
        // (then `lossy_threshold` is the only field) but required with it
        // (it also has `cross_size_rec6_probe`); allow rather than cfg-split.
        #[allow(clippy::needless_update)]
        let rs_lossy_encoded = if lossy_threshold > 0.0 {
            encode_jb2_dict_with_options(
                &bitmap,
                &[],
                &Jb2EncodeOptions {
                    lossy_threshold,
                    ..Default::default()
                },
            )
        } else {
            rs_dict_encoded.clone()
        };
        let lossy_hamming = if lossy_threshold > 0.0 {
            match jb2::decode(&rs_lossy_encoded, None) {
                Ok(d) => bitmap_hamming(&bitmap, &d),
                Err(_) => u64::MAX,
            }
        } else {
            0
        };

        let roundtrip = match jb2::decode(&rs_encoded, None) {
            Ok(b) => {
                if b.width == bitmap.width && b.height == bitmap.height && b.data == bitmap.data {
                    RoundtripStatus::Ok
                } else {
                    RoundtripStatus::Mismatch
                }
            }
            Err(_) => RoundtripStatus::DecodeError,
        };
        let roundtrip_dict = match jb2::decode(&rs_dict_encoded, None) {
            Ok(b) => {
                if b.width == bitmap.width && b.height == bitmap.height && b.data == bitmap.data {
                    RoundtripStatus::Ok
                } else {
                    RoundtripStatus::Mismatch
                }
            }
            Err(_) => RoundtripStatus::DecodeError,
        };

        out.push(PageResult {
            file: path.display().to_string(),
            page: page_idx,
            width: bitmap.width,
            height: bitmap.height,
            orig_sjbz_bytes: orig_sjbz.len(),
            rs_sjbz_bytes: rs_encoded.len(),
            rs_dict_sjbz_bytes: rs_dict_encoded.len(),
            rs_lossy_sjbz_bytes: rs_lossy_encoded.len(),
            lossy_hamming,
            roundtrip,
            roundtrip_dict,
        });
    }
    out
}

fn bpp(bytes: usize, width: u32, height: u32) -> f64 {
    if width == 0 || height == 0 {
        return f64::NAN;
    }
    (bytes as f64 * 8.0) / (width as f64 * height as f64)
}

fn main() -> ExitCode {
    let raw_args: Vec<String> = std::env::args().skip(1).collect();
    let mut lossy_threshold: f32 = 0.0;
    let mut files: Vec<String> = Vec::new();
    let mut i = 0;
    while i < raw_args.len() {
        let a = &raw_args[i];
        if a == "--lossy-threshold" {
            i += 1;
            if i >= raw_args.len() {
                eprintln!("--lossy-threshold requires a value (e.g. 0.04)");
                return ExitCode::from(2);
            }
            lossy_threshold = match raw_args[i].parse::<f32>() {
                Ok(v) if (0.0..=1.0).contains(&v) => v,
                _ => {
                    eprintln!(
                        "--lossy-threshold must be a fraction in [0.0, 1.0] (got {:?})",
                        raw_args[i]
                    );
                    return ExitCode::from(2);
                }
            };
        } else if let Some(rest) = a.strip_prefix("--lossy-threshold=") {
            lossy_threshold = match rest.parse::<f32>() {
                Ok(v) if (0.0..=1.0).contains(&v) => v,
                _ => {
                    eprintln!(
                        "--lossy-threshold must be a fraction in [0.0, 1.0] (got {:?})",
                        rest
                    );
                    return ExitCode::from(2);
                }
            };
        } else {
            files.push(a.clone());
        }
        i += 1;
    }

    if files.is_empty() {
        eprintln!(
            "usage: encode_quality_jb2 [--lossy-threshold <fraction>] <file.djvu> [<file2.djvu> ...]\n\
             \n\
             Re-encodes every Sjbz chunk via djvu-rs and compares size to the\n\
             original. Also verifies lossless round-trip.\n\
             \n\
             --lossy-threshold <f>  enable lossy rec-7 substitution at the given\n\
                                    Hamming fraction (e.g. 0.04 = 4%% of pixels).\n\
                                    Default 0 = lossless."
        );
        return ExitCode::from(2);
    }

    let mut all: Vec<PageResult> = Vec::new();
    for arg in &files {
        let path = Path::new(arg);
        all.extend(process_file(path, lossy_threshold));
    }

    for r in &all {
        println!(
            "{{\"file\":\"{}\",\"page\":{},\"width\":{},\"height\":{},\
             \"orig_sjbz_bytes\":{},\"rs_sjbz_bytes\":{},\"rs_dict_sjbz_bytes\":{},\
             \"rs_lossy_sjbz_bytes\":{},\"lossy_hamming\":{},\
             \"bpp_orig\":{:.4},\"bpp_rs\":{:.4},\"bpp_rs_dict\":{:.4},\"bpp_rs_lossy\":{:.4},\
             \"size_ratio\":{:.3},\"size_ratio_dict\":{:.3},\"size_ratio_lossy\":{:.3},\
             \"roundtrip\":\"{}\",\"roundtrip_dict\":\"{}\"}}",
            r.file,
            r.page,
            r.width,
            r.height,
            r.orig_sjbz_bytes,
            r.rs_sjbz_bytes,
            r.rs_dict_sjbz_bytes,
            r.rs_lossy_sjbz_bytes,
            r.lossy_hamming,
            bpp(r.orig_sjbz_bytes, r.width, r.height),
            bpp(r.rs_sjbz_bytes, r.width, r.height),
            bpp(r.rs_dict_sjbz_bytes, r.width, r.height),
            bpp(r.rs_lossy_sjbz_bytes, r.width, r.height),
            r.rs_sjbz_bytes as f64 / r.orig_sjbz_bytes.max(1) as f64,
            r.rs_dict_sjbz_bytes as f64 / r.orig_sjbz_bytes.max(1) as f64,
            r.rs_lossy_sjbz_bytes as f64 / r.orig_sjbz_bytes.max(1) as f64,
            r.roundtrip.as_str(),
            r.roundtrip_dict.as_str(),
        );
    }

    if all.is_empty() {
        eprintln!("no JB2 pages processed");
        return ExitCode::from(1);
    }

    let total_orig: usize = all.iter().map(|r| r.orig_sjbz_bytes).sum();
    let total_rs: usize = all.iter().map(|r| r.rs_sjbz_bytes).sum();
    let total_rs_dict: usize = all.iter().map(|r| r.rs_dict_sjbz_bytes).sum();
    let total_pixels: u64 = all.iter().map(|r| r.width as u64 * r.height as u64).sum();

    let roundtrip_ok = all
        .iter()
        .filter(|r| matches!(r.roundtrip, RoundtripStatus::Ok))
        .count();
    let roundtrip_mismatch = all
        .iter()
        .filter(|r| matches!(r.roundtrip, RoundtripStatus::Mismatch))
        .count();
    let roundtrip_decode_err = all
        .iter()
        .filter(|r| matches!(r.roundtrip, RoundtripStatus::DecodeError))
        .count();

    let roundtrip_dict_ok = all
        .iter()
        .filter(|r| matches!(r.roundtrip_dict, RoundtripStatus::Ok))
        .count();
    let roundtrip_dict_mismatch = all
        .iter()
        .filter(|r| matches!(r.roundtrip_dict, RoundtripStatus::Mismatch))
        .count();
    let roundtrip_dict_decode_err = all
        .iter()
        .filter(|r| matches!(r.roundtrip_dict, RoundtripStatus::DecodeError))
        .count();

    eprintln!();
    eprintln!("=== JB2 encoder quality summary ===");
    eprintln!("pages:                  {}", all.len());
    eprintln!();
    eprintln!("-- direct (record type 3, whole image) --");
    eprintln!("roundtrip ok:           {}", roundtrip_ok);
    eprintln!("roundtrip mismatch:     {}", roundtrip_mismatch);
    eprintln!(
        "roundtrip decode err:   {}   (issue #198: >1 MP single-symbol)",
        roundtrip_decode_err
    );
    eprintln!(
        "total rs size:       {:>10} bytes  ({:.4} bpp)",
        total_rs,
        (total_rs as f64 * 8.0) / total_pixels.max(1) as f64
    );
    eprintln!(
        "ratio rs / orig:     {:.3}×",
        total_rs as f64 / total_orig.max(1) as f64
    );
    eprintln!();
    eprintln!("-- dict (CC + rec types 1+7) --");
    eprintln!("roundtrip ok:           {}", roundtrip_dict_ok);
    eprintln!("roundtrip mismatch:     {}", roundtrip_dict_mismatch);
    eprintln!("roundtrip decode err:   {}", roundtrip_dict_decode_err);
    eprintln!(
        "total rs-dict size:  {:>10} bytes  ({:.4} bpp)",
        total_rs_dict,
        (total_rs_dict as f64 * 8.0) / total_pixels.max(1) as f64
    );
    eprintln!(
        "ratio rs-dict / orig: {:.3}×  (>1 = djvu-rs encoder worse)",
        total_rs_dict as f64 / total_orig.max(1) as f64
    );
    eprintln!();
    eprintln!(
        "total orig size:     {:>10} bytes  ({:.4} bpp)",
        total_orig,
        (total_orig as f64 * 8.0) / total_pixels.max(1) as f64
    );

    if lossy_threshold > 0.0 {
        let total_rs_lossy: usize = all.iter().map(|r| r.rs_lossy_sjbz_bytes).sum();
        let total_lossy_hamming: u64 = all
            .iter()
            .map(|r| {
                if r.lossy_hamming == u64::MAX {
                    0
                } else {
                    r.lossy_hamming
                }
            })
            .sum();
        let lossy_decode_err = all.iter().filter(|r| r.lossy_hamming == u64::MAX).count();
        eprintln!();
        eprintln!(
            "-- lossy dict (rec-7 near-dup substitution, threshold = {:.4}) --",
            lossy_threshold
        );
        eprintln!(
            "total rs-lossy size: {:>10} bytes  ({:.4} bpp)",
            total_rs_lossy,
            (total_rs_lossy as f64 * 8.0) / total_pixels.max(1) as f64
        );
        eprintln!(
            "ratio rs-lossy / orig:    {:.3}×",
            total_rs_lossy as f64 / total_orig.max(1) as f64
        );
        eprintln!(
            "ratio rs-lossy / rs-dict: {:.3}×",
            total_rs_lossy as f64 / total_rs_dict.max(1) as f64
        );
        eprintln!(
            "total reconstruction err: {} pixels  ({:.6} bits/pixel error)",
            total_lossy_hamming,
            total_lossy_hamming as f64 / total_pixels.max(1) as f64
        );
        eprintln!("lossy decode errors:      {}", lossy_decode_err);
    }

    if roundtrip_mismatch > 0 || roundtrip_dict_mismatch > 0 {
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}

