//! PDF export timing and memory probe.
//!
//! Usage:
//!   cargo run --release --example pdf_memory_probe -- tests/corpus/watchmaker.djvu
//!   cargo run --release --features parallel --example pdf_memory_probe -- tests/corpus/watchmaker.djvu
//!
//! For peak RSS, wrap the command with the platform time tool, for example:
//!   /usr/bin/time -l cargo run --release --example pdf_memory_probe -- tests/corpus/watchmaker.djvu
//!   /usr/bin/time -v cargo run --release --example pdf_memory_probe -- tests/corpus/watchmaker.djvu

use std::path::PathBuf;
use std::time::Instant;

use djvu_rs::djvu_document::DjVuDocument;
use djvu_rs::djvu_render::{RenderOptions, render_pixmap};
use djvu_rs::pdf::djvu_to_pdf;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut args = std::env::args_os().skip(1);
    let path = args.next().map(PathBuf::from).ok_or_else(|| {
        "usage: pdf_memory_probe <file.djvu> [page-index-for-breakdown]".to_string()
    })?;
    let page_index = args
        .next()
        .map(|v| v.to_string_lossy().parse::<usize>())
        .transpose()?
        .unwrap_or(0);

    let read_start = Instant::now();
    let data = std::fs::read(&path)?;
    let read_ms = read_start.elapsed().as_secs_f64() * 1000.0;

    let parse_start = Instant::now();
    let doc = DjVuDocument::parse(&data)?;
    let parse_ms = parse_start.elapsed().as_secs_f64() * 1000.0;

    let page_count = doc.page_count();
    let page = doc.page(page_index)?;
    let (rw, rh) = render_dims(
        u32::from(page.width()),
        u32::from(page.height()),
        u32::from(page.dpi().max(1)),
        150,
    );

    let (render_ms, rgba_bytes, rgb_ms, rgb_bytes, jpeg_ms, jpeg_len) = {
        let render_start = Instant::now();
        let pixmap = render_pixmap(
            page,
            &RenderOptions {
                width: rw,
                height: rh,
                ..RenderOptions::default()
            },
        )?;
        let render_ms = render_start.elapsed().as_secs_f64() * 1000.0;
        let rgba_bytes = pixmap.data.len();

        let rgb_start = Instant::now();
        let rgb = pixmap.to_rgb();
        let rgb_ms = rgb_start.elapsed().as_secs_f64() * 1000.0;
        let rgb_bytes = rgb.len();

        let jpeg_start = Instant::now();
        let jpeg_len = encode_rgb_to_jpeg_len(&rgb, rw, rh, 80);
        let jpeg_ms = jpeg_start.elapsed().as_secs_f64() * 1000.0;

        (render_ms, rgba_bytes, rgb_ms, rgb_bytes, jpeg_ms, jpeg_len)
    };

    let pdf_start = Instant::now();
    let pdf = djvu_to_pdf(&doc)?;
    let pdf_ms = pdf_start.elapsed().as_secs_f64() * 1000.0;

    println!("file={}", path.display());
    println!("input_bytes={}", data.len());
    println!("pages={page_count}");
    println!("read_ms={read_ms:.3}");
    println!("parse_ms={parse_ms:.3}");
    println!("breakdown_page={page_index}");
    println!("render_dims={}x{}", rw, rh);
    println!("render_pixmap_ms={render_ms:.3}");
    println!("rgba_bytes={rgba_bytes}");
    println!("rgb_stage_ms={rgb_ms:.3}");
    println!("rgb_bytes={rgb_bytes}");
    println!("jpeg_stage_ms={jpeg_ms:.3}");
    println!("jpeg_bytes={jpeg_len}");
    println!("pdf_export_ms={pdf_ms:.3}");
    println!("pdf_bytes={}", pdf.len());
    println!(
        "parallel_feature={}",
        if cfg!(feature = "parallel") {
            "enabled"
        } else {
            "disabled"
        }
    );

    Ok(())
}

fn render_dims(width: u32, height: u32, page_dpi: u32, output_dpi: u32) -> (u32, u32) {
    let target = if output_dpi == 0 {
        page_dpi
    } else {
        output_dpi
    };
    if target == page_dpi {
        return (width, height);
    }
    let scale = target as f64 / page_dpi as f64;
    (
        ((width as f64 * scale).round() as u32).max(1),
        ((height as f64 * scale).round() as u32).max(1),
    )
}

fn encode_rgb_to_jpeg_len(rgb: &[u8], width: u32, height: u32, quality: u8) -> usize {
    let mut jpeg = Vec::new();
    let encoder = jpeg_encoder::Encoder::new(&mut jpeg, quality);
    let _ = encoder.encode(
        rgb,
        width as u16,
        height as u16,
        jpeg_encoder::ColorType::Rgb,
    );
    jpeg.len()
}

//! Reproducible memory probe for the TIFF row-streaming export path.
//!
//! Build once, then run under the platform's time/RSS tool, for example:
//!
//! ```text
//! cargo build --release --features tiff --example probe_tiff_streaming_memory
//! /usr/bin/time -l target/release/examples/probe_tiff_streaming_memory \
//!   tests/fixtures/problem_page.djvu /tmp/problem_page_streamed.tiff 1.0
//! ```
//!
//! On Linux, use `/usr/bin/time -v` instead of `-l`.

// Names the deprecated, now-ignored `RenderOptions::scale` field (#377); allowed
// so this probe keeps building while the back-compat field exists.
#![allow(deprecated)]

use std::{env, error::Error, fs::File, path::PathBuf};

use djvu_rs::{
    djvu_document::DjVuDocument,
    tiff_export::{TiffOptions, djvu_to_tiff_writer},
};

fn main() -> Result<(), Box<dyn Error>> {
    let mut args = env::args_os().skip(1);
    let input = args.next().map(PathBuf::from).ok_or_else(usage)?;
    let output = args.next().map(PathBuf::from).ok_or_else(usage)?;
    let scale = args
        .next()
        .map(|s| s.to_string_lossy().parse::<f32>())
        .transpose()?
        .unwrap_or(1.0);

    let data = std::fs::read(&input)?;
    let doc = DjVuDocument::parse(&data)?;

    if let Some(parent) = output.parent()
        && !parent.as_os_str().is_empty()
    {
        std::fs::create_dir_all(parent)?;
    }

    let mut total_pixels = 0u64;
    for i in 0..doc.page_count() {
        let page = doc.page(i)?;
        let w = ((page.width() as f32 * scale).round() as u32).max(1);
        let h = ((page.height() as f32 * scale).round() as u32).max(1);
        total_pixels += u64::from(w) * u64::from(h);
        println!(
            "page {}: {}x{} px at scale {:.3} (source dpi {})",
            i + 1,
            w,
            h,
            scale,
            page.dpi()
        );
    }

    let file = File::create(&output)?;
    djvu_to_tiff_writer(
        &doc,
        &TiffOptions {
            scale,
            ..TiffOptions::default()
        },
        file,
    )?;

    let out_bytes = std::fs::metadata(&output)?.len();
    println!("pages: {}", doc.page_count());
    println!("output_tiff_bytes: {out_bytes}");
    println!("full_rgba_pixmap_bytes_avoided: {}", total_pixels * 4);
    println!("full_rgb_staging_bytes_avoided: {}", total_pixels * 3);
    println!(
        "measure peak RSS with /usr/bin/time (-l on macOS, -v on Linux); \
         the exporter writes to File and does not retain the TIFF byte buffer"
    );

    Ok(())
}

fn usage() -> String {
    "usage: probe_tiff_streaming_memory <input.djvu> <output.tiff> [scale]".to_string()
}

//! Profiling harness for IW44 reconstruct (scatter + wavelet + YCbCr).
//!
//! Decodes colorbook.djvu page 0 in a tight loop so that samply / Instruments
//! can collect meaningful samples and show the scatter-vs-wavelet split.
//!
//! Usage:
//!   cargo build --release --example profile_iw44
//!   samply record ./target/release/examples/profile_iw44

fn main() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("references/djvujs/library/assets/colorbook.djvu");

    let data = std::fs::read(&path).unwrap_or_else(|_| {
        eprintln!("ERROR: {} not found", path.display());
        std::process::exit(1);
    });

    let doc = djvu_rs::DjVuDocument::parse(&data).expect("parse failed");
    let page = doc.page(0).expect("page 0 not found");

    // Pre-decode all BG44 chunks (ZP decode) — benchmark only reconstruct.
    let chunks: Vec<Vec<u8>> = page
        .bg44_chunks()
        .iter()
        .map(|s: &&[u8]| s.to_vec())
        .collect();
    if chunks.is_empty() {
        eprintln!("ERROR: no BG44 chunks found");
        std::process::exit(1);
    }

    let mut img = djvu_rs::iw44_new::Iw44Image::new();
    for chunk in &chunks {
        img.decode_chunk(chunk).expect("decode_chunk failed");
    }

    // Warm up
    for _ in 0..3 {
        let _ = std::hint::black_box(img.to_rgb());
    }

    // Hot loop — enough iterations for stable samply samples (~8 s)
    let iters = 500;
    let t0 = std::time::Instant::now();
    for _ in 0..iters {
        let _ = std::hint::black_box(img.to_rgb());
    }
    let elapsed = t0.elapsed();
    eprintln!(
        "{iters} iters in {:.1}ms ({:.2}ms/iter)",
        elapsed.as_secs_f64() * 1000.0,
        elapsed.as_secs_f64() * 1000.0 / iters as f64,
    );
}

