//! Investigation: why is iw44_decode_corpus_color ~17× slower than jb2_decode?
#![allow(dead_code)]
use std::path::PathBuf;
use std::time::Instant;

fn time_iters<F: FnMut()>(mut f: F, n: u32) -> f64 {
    let t = Instant::now();
    for _ in 0..n {
        f();
    }
    t.elapsed().as_micros() as f64 / n as f64
}

fn find_sjbz(data: &[u8]) -> Option<Vec<u8>> {
    fn walk(chunks: &[djvu_rs::iff::Chunk], id: &[u8; 4]) -> Option<Vec<u8>> {
        for c in chunks {
            match c {
                djvu_rs::iff::Chunk::Leaf { id: cid, data } if cid == id => {
                    return Some(data.clone());
                }
                djvu_rs::iff::Chunk::Form { children, .. } => {
                    if let Some(r) = walk(children, id) {
                        return Some(r);
                    }
                }
                _ => {}
            }
        }
        None
    }
    let f = djvu_rs::iff::parse(data).ok()?;
    walk(f.root.children(), b"Sjbz")
}

fn main() {
    let assets = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("references/djvujs/library/assets");
    let corpus = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/corpus");

    println!("=== File / chunk inventory ===\n");
    for (label, path) in [
        (
            "boy_jb2.djvu (jb2_decode benchmark)",
            assets.join("boy_jb2.djvu"),
        ),
        (
            "boy.djvu    (iw44_first_chunk benchmark)",
            assets.join("boy.djvu"),
        ),
        (
            "watchmaker  (iw44_corpus_color benchmark)",
            corpus.join("watchmaker.djvu"),
        ),
        (
            "cable_1973  (jb2_corpus_bilevel benchmark)",
            corpus.join("cable_1973_100133.djvu"),
        ),
    ] {
        let data = match std::fs::read(&path) {
            Ok(d) => d,
            Err(e) => {
                println!("{label}: SKIP ({e})\n");
                continue;
            }
        };
        let doc = djvu_rs::DjVuDocument::parse(&data).unwrap();
        let page = doc.page(0).unwrap();
        let _ids: Vec<String> = page
            .chunk_ids()
            .iter()
            .map(|id| String::from_utf8_lossy(id).into_owned())
            .collect();
        println!("{label}: {}×{}", page.width(), page.height());
        for id in page.chunk_ids() {
            if let Some(d) = page.raw_chunk(&id)
                && !d.is_empty()
            {
                println!("  {:4}: {} bytes", String::from_utf8_lossy(&id), d.len());
            }
        }
        let iw44_blocks =
            (page.width() as usize).div_ceil(32) * (page.height() as usize).div_ceil(32);
        println!(
            "  IW44 block grid: {}×{} = {} blocks, block alloc = {:.2} MB",
            (page.width() as usize).div_ceil(32),
            (page.height() as usize).div_ceil(32),
            iw44_blocks,
            iw44_blocks as f64 * 1024.0 * 2.0 / 1e6
        );
        println!();
    }

    println!("=== Timing ===\n");
    struct Case {
        label: &'static str,
        bytes: usize,
        blocks: usize,
        us: f64,
    }
    let mut cases: Vec<Case> = vec![];

    // jb2_decode: boy_jb2.djvu
    {
        let data = std::fs::read(assets.join("boy_jb2.djvu")).unwrap();
        let sjbz = find_sjbz(&data).unwrap();
        let doc = djvu_rs::DjVuDocument::parse(&data).unwrap();
        let page = doc.page(0).unwrap();
        println!(
            "boy_jb2.djvu page: {}×{}, Sjbz = {} bytes",
            page.width(),
            page.height(),
            sjbz.len()
        );
        let us = time_iters(
            || {
                let _ = djvu_rs::jb2::decode(&sjbz, None);
            },
            500,
        );
        cases.push(Case {
            label: "jb2_decode [boy_jb2.djvu]",
            bytes: sjbz.len(),
            blocks: 0,
            us,
        });
    }

    // iw44_first_chunk: boy.djvu BG44
    {
        let data = std::fs::read(assets.join("boy.djvu")).unwrap();
        let doc = djvu_rs::DjVuDocument::parse(&data).unwrap();
        let page = doc.page(0).unwrap();
        let bg44 = page.bg44_chunks().first().unwrap().to_vec();
        let blocks = (page.width() as usize).div_ceil(32) * (page.height() as usize).div_ceil(32);
        println!(
            "boy.djvu page: {}×{}, BG44[0] = {} bytes, {} blocks ({:.2} MB alloc)",
            page.width(),
            page.height(),
            bg44.len(),
            blocks,
            blocks as f64 * 1024.0 * 2.0 / 1e6
        );
        let us = time_iters(
            || {
                let mut img = djvu_rs::iw44_new::Iw44Image::new();
                let _ = img.decode_chunk(&bg44);
            },
            500,
        );
        // Isolate block allocation cost
        let alloc_us = time_iters(
            || {
                let _ = vec![[0i16; 1024]; blocks];
            },
            500,
        );
        println!("  alloc {} blocks = {:.2} µs", blocks, alloc_us);
        cases.push(Case {
            label: "iw44_first_chunk [boy.djvu]",
            bytes: bg44.len(),
            blocks,
            us,
        });
    }

    // iw44_corpus_color: watchmaker BG44 first chunk
    {
        let data = match std::fs::read(corpus.join("watchmaker.djvu")) {
            Ok(d) => d,
            Err(e) => {
                println!("watchmaker: SKIP ({e})");
                return;
            }
        };
        let doc = djvu_rs::DjVuDocument::parse(&data).unwrap();
        let page = doc.page(0).unwrap();
        let bg44 = page.bg44_chunks().first().unwrap().to_vec();
        let blocks = (page.width() as usize).div_ceil(32) * (page.height() as usize).div_ceil(32);
        println!(
            "watchmaker.djvu page: {}×{}, BG44[0] = {} bytes, {} blocks ({:.2} MB alloc)",
            page.width(),
            page.height(),
            bg44.len(),
            blocks,
            blocks as f64 * 1024.0 * 2.0 / 1e6
        );
        let us = time_iters(
            || {
                let mut img = djvu_rs::iw44_new::Iw44Image::new();
                let _ = img.decode_chunk(&bg44);
            },
            200,
        );
        // Isolate block allocation cost
        let alloc_us = time_iters(
            || {
                let _ = vec![[0i16; 1024]; blocks];
            },
            500,
        );
        println!("  alloc {} blocks = {:.2} µs", blocks, alloc_us);
        println!(
            "  ZP decode estimate (total - alloc) = {:.1} µs",
            us - alloc_us
        );
        cases.push(Case {
            label: "iw44_corpus_color [watchmaker]",
            bytes: bg44.len(),
            blocks,
            us,
        });
    }
    println!();

    // ── Results table ────────────────────────────────────────────────────────
    println!("{:-<78}", "");
    println!(
        "{:<40} {:>6} {:>7} {:>8} {:>10}",
        "Benchmark", "Bytes", "Blocks", "µs", "MB/s (ZP)"
    );
    println!("{:-<78}", "");
    for c in &cases {
        let mbps = c.bytes as f64 / (c.us * 1e-6) / 1e6;
        println!(
            "{:<40} {:>6} {:>7} {:>8.1} {:>10.2}",
            c.label,
            c.bytes,
            if c.blocks > 0 {
                c.blocks.to_string()
            } else {
                "-".into()
            },
            c.us,
            mbps
        );
    }
    println!("{:-<78}", "");
}

