/// Render a page at the given DPI. Returns NULL on error.
/// Caller must free with `djvu_pixmap_free`.
///
/// # Safety
///
/// `doc` must be a valid pointer returned by `djvu_doc_open`.
/// `err` must be null or point to a valid `DjvuError`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn djvu_page_render(
    doc: *const DjvuDoc,
    page: usize,
    dpi: f32,
    err: *mut DjvuError,
) -> *mut DjvuPixmap {
    guard(err, std::ptr::null_mut(), 2, "panic during render", || {
        let doc = unsafe { doc_ref(doc)? };
        let pixmap = foreign::render_at_dpi(doc, page, dpi)?;
        Ok(Box::into_raw(Box::new(DjvuPixmap { inner: pixmap })))
    })
}

/// Free a pixmap handle.
///
/// # Safety
///
/// `pm` must be null or a pointer returned by `djvu_page_render` that has not
/// yet been freed.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn djvu_pixmap_free(pm: *mut DjvuPixmap) {
    if !pm.is_null() {
        unsafe { drop(Box::from_raw(pm)) };
    }
}

/// Get pixmap width.
///
/// # Safety
///
/// `pm` must be null or a valid pointer returned by `djvu_page_render`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn djvu_pixmap_width(pm: *const DjvuPixmap) -> u32 {
    if pm.is_null() {
        return 0;
    }
    unsafe { (*pm).inner.width }
}

/// Get pixmap height.
///
/// # Safety
///
/// `pm` must be null or a valid pointer returned by `djvu_page_render`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn djvu_pixmap_height(pm: *const DjvuPixmap) -> u32 {
    if pm.is_null() {
        return 0;
    }
    unsafe { (*pm).inner.height }
}

/// Get pointer to RGBA pixel data. Length = width * height * 4.
/// The pointer is valid until `djvu_pixmap_free` is called.
///
/// # Safety
///
/// `pm` must be null or a valid pointer returned by `djvu_page_render`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn djvu_pixmap_data(pm: *const DjvuPixmap) -> *const u8 {
    if pm.is_null() {
        return std::ptr::null();
    }
    unsafe { (*pm).inner.data.as_ptr() }
}

/// Get the length of the pixmap data buffer in bytes.
///
/// # Safety
///
/// `pm` must be null or a valid pointer returned by `djvu_page_render`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn djvu_pixmap_data_len(pm: *const DjvuPixmap) -> usize {
    if pm.is_null() {
        return 0;
    }
    unsafe { (*pm).inner.data.len() }
}

/// Extract text from a page. Returns NULL if no text layer.
/// Caller must free with `djvu_text_free`.
///
/// # Safety
///
/// `doc` must be a valid pointer returned by `djvu_doc_open`.
/// `err` must be null or point to a valid `DjvuError`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn djvu_page_text(
    doc: *const DjvuDoc,
    page: usize,
    err: *mut DjvuError,
) -> *mut c_char {
    guard(
        err,
        std::ptr::null_mut(),
        2,
        "panic during text extraction",
        || {
            let doc = unsafe { doc_ref(doc)? };
            match foreign::text(doc, page)? {
                Some(text) => {
                    let c = CString::new(text).map_err(|e| ForeignError::Decode(e.to_string()))?;
                    Ok(c.into_raw())
                }
                None => Ok(std::ptr::null_mut()),
            }
        },
    )
}

/// Free a text string returned by `djvu_page_text`.
///
/// # Safety
///
/// `text` must be null or a pointer returned by `djvu_page_text` that has not
/// yet been freed.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn djvu_text_free(text: *mut c_char) {
    if !text.is_null() {
        unsafe { drop(CString::from_raw(text)) };
    }
}

//! FGbz foreground-palette parser.
//!
//! Decodes the `FGbz` chunk payload into a color palette and an optional
//! per-blit color-index table. The render module consumes the already-decoded
//! [`FgbzPalette`]; keeping the parser here means [`crate::djvu_render`] never
//! touches BZZ directly — the only `bzz_decode` call for the index table lives
//! in this module.

#[cfg(not(feature = "std"))]
use alloc::vec::Vec;

use crate::error::BzzError;

/// An RGB color from the FGbz palette.
#[derive(Debug, Clone, Copy, Default)]
pub(crate) struct PaletteColor {
    pub(crate) r: u8,
    pub(crate) g: u8,
    pub(crate) b: u8,
}

/// Parsed FGbz data: palette colors and optional per-blit color indices.
pub(crate) struct FgbzPalette {
    pub(crate) colors: Vec<PaletteColor>,
    /// Per-blit color index: `indices[blit_idx]` → index into `colors`.
    /// Empty when the FGbz chunk has no index table (version bit 7 unset).
    pub(crate) indices: Vec<i16>,
}

/// Parse the FGbz chunk into palette colors and per-blit index table.
///
/// FGbz format:
/// - byte 0: version (bit 7 = has index table, bits 6-0 must be 0)
/// - byte 1-2: big-endian u16 palette size (number of colors)
/// - next `palette_size * 3` bytes: BGR triples (raw if version=0, BZZ if version has bit 0 set)
/// - if bit 7 set: 3-byte big-endian count + BZZ-compressed i16be index table
pub(crate) fn parse_fgbz(data: &[u8]) -> Result<FgbzPalette, BzzError> {
    if data.len() < 3 {
        return Ok(FgbzPalette {
            colors: Vec::new(),
            indices: Vec::new(),
        });
    }

    let version = data[0];
    let has_indices = (version & 0x80) != 0;

    let n_colors =
        u16::from_be_bytes([*data.get(1).unwrap_or(&0), *data.get(2).unwrap_or(&0)]) as usize;

    if n_colors == 0 {
        return Ok(FgbzPalette {
            colors: Vec::new(),
            indices: Vec::new(),
        });
    }

    // Colors: raw BGR triples starting at byte 3
    let color_bytes = n_colors * 3;
    let color_data = data.get(3..).unwrap_or(&[]);

    let mut colors = Vec::with_capacity(n_colors);
    for i in 0..n_colors {
        let base = i * 3;
        if base + 2 < color_data.len().min(color_bytes) {
            colors.push(PaletteColor {
                r: color_data[base + 2],
                g: color_data[base + 1],
                b: color_data[base],
            });
        } else {
            colors.push(PaletteColor { r: 0, g: 0, b: 0 });
        }
    }

    // Per-blit index table
    let mut indices = Vec::new();
    if has_indices {
        let idx_start = 3 + color_bytes;
        if idx_start + 3 <= data.len() {
            let num_indices = ((data[idx_start] as u32) << 16)
                | ((data[idx_start + 1] as u32) << 8)
                | (data[idx_start + 2] as u32);

            let bzz_data = data.get(idx_start + 3..).unwrap_or(&[]);
            let decoded = crate::bzz_new::bzz_decode(bzz_data)?;

            let n = num_indices as usize;
            indices.reserve(n);
            for i in 0..n {
                if i * 2 + 1 < decoded.len() {
                    indices.push(i16::from_be_bytes([decoded[i * 2], decoded[i * 2 + 1]]));
                }
            }
        }
    }

    Ok(FgbzPalette { colors, indices })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_fgbz_short_data_returns_empty() {
        // data.len() < 3 → empty palette
        let result = parse_fgbz(&[]).unwrap();
        assert!(result.colors.is_empty());
        assert!(result.indices.is_empty());

        let result = parse_fgbz(&[0x00, 0x00]).unwrap();
        assert!(result.colors.is_empty());
    }

    #[test]
    fn parse_fgbz_zero_colors_returns_empty() {
        // version=0, n_colors=0 → empty palette
        let data = [0x00u8, 0x00, 0x00]; // version, n_colors (u16be) = 0
        let result = parse_fgbz(&data).unwrap();
        assert!(result.colors.is_empty());
    }

    #[test]
    fn parse_fgbz_truncated_color_data_fills_black() {
        // n_colors=2 but only 3 bytes of color data (1 full color, 1 truncated)
        let mut data = Vec::new();
        data.push(0x00); // version: no index table
        data.extend_from_slice(&2u16.to_be_bytes()); // n_colors = 2
        // Only 3 bytes for first color (BGR): b=10, g=20, r=30
        data.extend_from_slice(&[10, 20, 30]);
        // Second color is truncated (not enough bytes)
        let result = parse_fgbz(&data).unwrap();
        assert_eq!(result.colors.len(), 2);
        // First color parsed: r=30, g=20, b=10
        assert_eq!(result.colors[0].r, 30);
        // Second color falls back to black (0,0,0)
        assert_eq!(result.colors[1].r, 0);
        assert_eq!(result.colors[1].g, 0);
        assert_eq!(result.colors[1].b, 0);
    }
}

//! FGbz foreground palette encoder — produces FGbz chunk payloads.
//!
//! Encoding counterpart to the decoder in [`crate::djvu_render`]
//! (`parse_fgbz`). FGbz carries the foreground palette of DjVu's "color
//! text" layered model: a flat 24-bit palette plus an optional table of
//! per-blit indices selecting which palette entry colours each Sjbz
//! shape on the page.
//!
//! ## Wire format
//!
//! ```text
//! byte 0:        version; bit 7 set ⇒ index table follows; other bits MBZ
//! bytes 1..3:    big-endian u16 — palette size N (≤ 65 535)
//! bytes 3..3+3N: N × BGR triples (one byte each: B, G, R) — raw, not BZZ
//! if bit 7 set:
//!     bytes [3+3N .. 3+3N+3]: big-endian u24 — index count M (≤ 2²⁴−1)
//!     bytes [3+3N+3 ..]:      BZZ-compressed payload of M × i16 (BE)
//! ```
//!
//! Round-trip is bit-exact for the raw palette section. The index
//! section is round-trip-equal at the *value* level (the BZZ envelope
//! may differ byte-for-byte vs. another implementation, since BZZ is
//! not canonical, but `decode(encode(idx)) == idx`).

use crate::bzz_encode::bzz_encode;
use crate::bzz_new::bzz_decode;
use crate::chunk_encode::EncodeError;
use crate::error::DjVuError;

/// One palette entry (24-bit RGB).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct FgbzColor {
    pub r: u8,
    pub g: u8,
    pub b: u8,
}

/// Encode an FGbz chunk payload from a palette and optional per-blit
/// index table.
///
/// # Errors
///
/// - [`EncodeError::PaletteOverflow`] if `palette.len() > 65 535`.
/// - [`EncodeError::IndexCountOverflow`] if `indices.map(len) ≥ 2²⁴`.
///
/// Both are wire-format limits; this replaces the previous `assert!` panic.
pub fn encode_fgbz(palette: &[FgbzColor], indices: Option<&[i16]>) -> Result<Vec<u8>, EncodeError> {
    if palette.len() > u16::MAX as usize {
        return Err(EncodeError::PaletteOverflow {
            found: palette.len(),
        });
    }
    if let Some(idx) = indices
        && idx.len() >= (1usize << 24)
    {
        return Err(EncodeError::IndexCountOverflow { found: idx.len() });
    }

    let cap = 3 + palette.len() * 3 + indices.map_or(0, |i| 3 + i.len() * 2);
    let mut out = Vec::with_capacity(cap);

    out.push(if indices.is_some() { 0x80 } else { 0 });
    out.extend_from_slice(&(palette.len() as u16).to_be_bytes());

    for c in palette {
        out.push(c.b);
        out.push(c.g);
        out.push(c.r);
    }

    if let Some(idx) = indices {
        let n = idx.len() as u32;
        out.push(((n >> 16) & 0xff) as u8);
        out.push(((n >> 8) & 0xff) as u8);
        out.push((n & 0xff) as u8);

        let mut raw = Vec::with_capacity(idx.len() * 2);
        for &v in idx {
            raw.extend_from_slice(&v.to_be_bytes());
        }
        out.extend_from_slice(&bzz_encode(&raw));
    }

    Ok(out)
}

/// Decode an FGbz chunk payload.
///
/// Inverse of [`encode_fgbz`] — returns the palette and (when present)
/// the per-blit index table. Independent of the renderer's internal
/// `parse_fgbz`; both share the same wire spec.
pub fn decode_fgbz(data: &[u8]) -> Result<(Vec<FgbzColor>, Vec<i16>), DjVuError> {
    if data.len() < 3 {
        return Ok((Vec::new(), Vec::new()));
    }

    let version = data[0];
    let has_indices = (version & 0x80) != 0;
    if version & 0x7f != 0 {
        return Err(DjVuError::InvalidStructure(
            "FGbz: reserved version bits set",
        ));
    }

    let n_colors = u16::from_be_bytes([data[1], data[2]]) as usize;
    let color_bytes = n_colors * 3;
    if data.len() < 3 + color_bytes {
        return Err(DjVuError::InvalidStructure("FGbz: palette truncated"));
    }

    let mut colors = Vec::with_capacity(n_colors);
    for i in 0..n_colors {
        let base = 3 + i * 3;
        colors.push(FgbzColor {
            b: data[base],
            g: data[base + 1],
            r: data[base + 2],
        });
    }

    let mut indices = Vec::new();
    if has_indices {
        let idx_start = 3 + color_bytes;
        if idx_start + 3 > data.len() {
            return Err(DjVuError::InvalidStructure("FGbz: index header truncated"));
        }
        let m = ((data[idx_start] as u32) << 16)
            | ((data[idx_start + 1] as u32) << 8)
            | (data[idx_start + 2] as u32);
        let bzz = &data[idx_start + 3..];
        let raw = bzz_decode(bzz)?;
        if raw.len() < (m as usize) * 2 {
            return Err(DjVuError::InvalidStructure(
                "FGbz: index payload shorter than declared count",
            ));
        }
        indices.reserve(m as usize);
        for i in 0..(m as usize) {
            indices.push(i16::from_be_bytes([raw[i * 2], raw[i * 2 + 1]]));
        }
    }

    Ok((colors, indices))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty_palette_no_indices() {
        let bytes = encode_fgbz(&[], None).unwrap();
        assert_eq!(bytes, [0x00, 0x00, 0x00]);
        let (colors, idx) = decode_fgbz(&bytes).unwrap();
        assert!(colors.is_empty());
        assert!(idx.is_empty());
    }

    #[test]
    fn palette_only_byte_layout() {
        let palette = [
            FgbzColor {
                r: 0x11,
                g: 0x22,
                b: 0x33,
            },
            FgbzColor {
                r: 0xaa,
                g: 0xbb,
                b: 0xcc,
            },
        ];
        let bytes = encode_fgbz(&palette, None).unwrap();
        // version=0, n=0x0002, then BGR triples
        assert_eq!(
            bytes,
            [0x00, 0x00, 0x02, 0x33, 0x22, 0x11, 0xcc, 0xbb, 0xaa]
        );
    }

    #[test]
    fn version_byte_signals_index_presence() {
        let palette = [FgbzColor { r: 1, g: 2, b: 3 }];
        let with_idx = encode_fgbz(&palette, Some(&[0])).unwrap();
        let without_idx = encode_fgbz(&palette, None).unwrap();
        assert_eq!(with_idx[0] & 0x80, 0x80);
        assert_eq!(without_idx[0] & 0x80, 0x00);
    }

    #[test]
    fn roundtrip_palette_only() {
        let palette: Vec<FgbzColor> = (0..256)
            .map(|i| FgbzColor {
                r: i as u8,
                g: (i * 3) as u8,
                b: (i * 7) as u8,
            })
            .collect();
        let bytes = encode_fgbz(&palette, None).unwrap();
        let (decoded, idx) = decode_fgbz(&bytes).unwrap();
        assert_eq!(decoded, palette);
        assert!(idx.is_empty());
    }

    #[test]
    fn roundtrip_with_indices() {
        let palette = [
            FgbzColor { r: 255, g: 0, b: 0 },
            FgbzColor { r: 0, g: 255, b: 0 },
            FgbzColor { r: 0, g: 0, b: 255 },
        ];
        let indices: Vec<i16> = (0..1000).map(|i| (i % 3) as i16).collect();
        let bytes = encode_fgbz(&palette, Some(&indices)).unwrap();
        let (dp, di) = decode_fgbz(&bytes).unwrap();
        assert_eq!(dp.as_slice(), palette.as_slice());
        assert_eq!(di, indices);
    }

    #[test]
    fn roundtrip_negative_indices_preserved() {
        // Per the wire spec, indices are signed i16. -1 is sometimes used
        // by encoders to mean "no palette entry / transparent".
        let palette = [FgbzColor { r: 1, g: 2, b: 3 }];
        let indices: Vec<i16> = vec![0, -1, 0, -1, 0];
        let bytes = encode_fgbz(&palette, Some(&indices)).unwrap();
        let (_, di) = decode_fgbz(&bytes).unwrap();
        assert_eq!(di, indices);
    }

    #[test]
    fn roundtrip_via_renderer_parse_fgbz() {
        // Sanity-check that our wire output is byte-compatible with the
        // renderer's independent `parse_fgbz` implementation in
        // `djvu_render` — they must agree on the spec.
        let palette = [
            FgbzColor {
                r: 10,
                g: 20,
                b: 30,
            },
            FgbzColor {
                r: 40,
                g: 50,
                b: 60,
            },
            FgbzColor {
                r: 70,
                g: 80,
                b: 90,
            },
        ];
        let indices: Vec<i16> = vec![0, 1, 2, 1, 0, 2];
        let bytes = encode_fgbz(&palette, Some(&indices)).unwrap();

        let parsed = crate::fgbz::parse_fgbz(&bytes).expect("parse_fgbz");
        assert_eq!(parsed.colors.len(), palette.len());
        for (a, b) in parsed.colors.iter().zip(palette.iter()) {
            assert_eq!((a.r, a.g, a.b), (b.r, b.g, b.b));
        }
        assert_eq!(parsed.indices, indices);
    }

    #[test]
    fn decode_rejects_truncated_palette() {
        // Declared 5 colours but only 1 BGR triple of bytes after the header.
        let bytes = [0x00, 0x00, 0x05, 0x01, 0x02, 0x03];
        assert!(decode_fgbz(&bytes).is_err());
    }

    #[test]
    fn decode_short_data_returns_empty() {
        let (colors, idx) = decode_fgbz(&[]).unwrap();
        assert!(colors.is_empty());
        assert!(idx.is_empty());
        let (colors2, _) = decode_fgbz(&[0x00, 0x00]).unwrap();
        assert!(colors2.is_empty());
    }

    #[test]
    fn decode_rejects_reserved_version_bits() {
        // version byte = 0x01 → lower 7 bits non-zero → reserved bits set
        let data = [0x01u8, 0x00, 0x00];
        assert!(decode_fgbz(&data).is_err());
    }

    #[test]
    fn decode_rejects_index_payload_too_short() {
        // BZZ-encode 2 bytes (enough for 1 i16), but declare m=2 (needs 4 bytes).
        // This makes bzz_decode succeed but raw.len()=2 < m*2=4 → line 133 error.
        let bzz = crate::bzz_encode::bzz_encode(&[0x00, 0x01]);
        let mut data = Vec::new();
        data.push(0x80); // version: has index table
        data.extend_from_slice(&1u16.to_be_bytes()); // n_colors = 1
        data.extend_from_slice(&[0x01, 0x02, 0x03]); // BGR triple
        data.extend_from_slice(&[0x00, 0x00, 0x02]); // m = 2 (needs 4 decoded bytes)
        data.extend_from_slice(&bzz); // encodes only 2 bytes
        assert!(decode_fgbz(&data).is_err());
    }

    #[test]
    fn decode_rejects_truncated_index_header() {
        // version=0x80 (has indices), 1 colour, then nothing.
        let bytes = [0x80, 0x00, 0x01, 0x01, 0x02, 0x03];
        assert!(decode_fgbz(&bytes).is_err());
    }
}

//! Shared core for the foreign-language bindings (#379).
//!
//! The C ABI (`crate::ffi`) and the wasm-bindgen surface (`crate::wasm`) are
//! two adapters over the same flow — open a document, query page size, render
//! a page to an RGBA buffer, extract text — and each used to re-translate the
//! typed [`DocError`]/[`RenderError`] into a string at every call site, from
//! two different parse entry points.
//!
//! This module is the single home for that flow:
//!
//!  * [`open`] — the one parse entry point both bindings use
//!    ([`DjVuDocument::parse`]); the C binding no longer routes through the
//!    legacy `Document` facade and its second error wrapping.
//!  * [`page_width`] / [`page_height`] / [`page_dpi`] / [`text`] /
//!    [`render_at_dpi`] — the per-page operations, each mapping the model
//!    error into the shared [`ForeignError`] taxonomy.
//!  * [`render_opts_for_dpi`] — the canonical [`RenderOptions`] for a target
//!    DPI (AA off so the RGBA length stays `w * h * 4`; permissive so a
//!    partially-corrupt page yields a best-effort image rather than failing).
//!
//! Each binding then adds only its target-specific cap: `CString` lifecycle
//! and a `catch_unwind` panic boundary for C, `JsError` conversion for wasm.
//! A new foreign function is one core function plus a thin cap.

use crate::djvu_document::{DjVuDocument, DjVuPage, DocError};
use crate::djvu_render::{self, RenderError, RenderOptions};
use crate::pixmap::Pixmap;

/// Error taxonomy shared by every foreign binding.
///
/// The variant determines the stable integer [`code`](ForeignError::code) the
/// C ABI exposes; the wasm binding uses the [`Display`] message. Centralizing
/// it means an "out of range" failure carries the same code regardless of
/// which entry point surfaced it — previously the C codes were assigned
/// per-call-site and disagreed (a bad page index was `2` from render/text but
/// `3` from the size queries).
#[derive(Debug)]
pub(crate) enum ForeignError {
    /// The document could not be parsed. Code `1`.
    Parse(String),
    /// A page's content could not be decoded or rendered. Code `2`.
    Decode(String),
    /// A page index was out of range (or a handle was null). Code `3`.
    OutOfRange(String),
}

impl ForeignError {
    /// The stable C ABI error code: `1` parse, `2` decode/render, `3` range.
    pub(crate) fn code(&self) -> i32 {
        match self {
            ForeignError::Parse(_) => 1,
            ForeignError::Decode(_) => 2,
            ForeignError::OutOfRange(_) => 3,
        }
    }

    /// Classify an error from page lookup: a genuine out-of-range index is
    /// [`OutOfRange`](ForeignError::OutOfRange); anything else that surfaces
    /// while resolving a page is a [`Decode`](ForeignError::Decode) failure.
    fn from_page_lookup(e: DocError) -> Self {
        match e {
            DocError::PageOutOfRange { .. } => ForeignError::OutOfRange(e.to_string()),
            other => ForeignError::Decode(other.to_string()),
        }
    }
}

impl core::fmt::Display for ForeignError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            ForeignError::Parse(m) | ForeignError::Decode(m) | ForeignError::OutOfRange(m) => {
                f.write_str(m)
            }
        }
    }
}

/// Parse a DjVu document from bytes — the single entry point both bindings
/// share.
pub(crate) fn open(data: &[u8]) -> Result<DjVuDocument, ForeignError> {
    DjVuDocument::parse(data).map_err(|e| ForeignError::Parse(e.to_string()))
}

/// Resolve page `index`, mapping a lookup failure into the shared taxonomy.
pub(crate) fn page(doc: &DjVuDocument, index: usize) -> Result<&DjVuPage, ForeignError> {
    doc.page(index).map_err(ForeignError::from_page_lookup)
}

/// Width in pixels of page `index`.
pub(crate) fn page_width(doc: &DjVuDocument, index: usize) -> Result<u32, ForeignError> {
    Ok(page(doc, index)?.width() as u32)
}

/// Height in pixels of page `index`.
pub(crate) fn page_height(doc: &DjVuDocument, index: usize) -> Result<u32, ForeignError> {
    Ok(page(doc, index)?.height() as u32)
}

/// Native DPI of page `index`.
pub(crate) fn page_dpi(doc: &DjVuDocument, index: usize) -> Result<u32, ForeignError> {
    Ok(page(doc, index)?.dpi() as u32)
}

/// Plain text of page `index`, or `None` when the page has no text layer.
pub(crate) fn text(doc: &DjVuDocument, index: usize) -> Result<Option<String>, ForeignError> {
    page(doc, index)?
        .text()
        .map_err(|e| ForeignError::Decode(e.to_string()))
}

/// Canonical [`RenderOptions`] for rendering `page` at `target_dpi`.
///
/// Anti-aliasing is disabled so the output is always exactly
/// `width * height * 4` RGBA bytes, and rendering is permissive so a page with
/// a few corrupt chunks still yields a best-effort image instead of an error —
/// the right default for a viewer-facing binding.
pub(crate) fn render_opts_for_dpi(page: &DjVuPage, target_dpi: f32) -> RenderOptions {
    let (width, height) = crate::export_common::size_at_dpi(page, target_dpi);
    // Only the size is set; the pipeline derives the decode scale from `width`
    // (see `RenderOptions::decode_scale`). `permissive` is the viewer-facing
    // default; the rest come from `RenderOptions::default()`.
    RenderOptions {
        width,
        height,
        permissive: true,
        ..RenderOptions::default()
    }
}

/// Render page `index` at `target_dpi` to an RGBA [`Pixmap`].
pub(crate) fn render_at_dpi(
    doc: &DjVuDocument,
    index: usize,
    target_dpi: f32,
) -> Result<Pixmap, ForeignError> {
    let page = page(doc, index)?;
    let opts = render_opts_for_dpi(page, target_dpi);
    djvu_render::render_pixmap(page, &opts).map_err(map_render_err)
}

/// Map a [`RenderError`] into the shared taxonomy (always a decode failure).
pub(crate) fn map_render_err(e: RenderError) -> ForeignError {
    ForeignError::Decode(e.to_string())
}

//! Backwards-compatible IFF module.
//!
//! The implementation lives in the standalone `djvu-iff` crate. This module
//! preserves the historical `djvu_rs::iff::*` path.

pub use djvu_iff::*;

//! `image::ImageDecoder` integration for DjVu pages.
//!
//! This module provides [`DjVuDecoder`], which implements the
//! [`image::ImageDecoder`] and [`image::ImageDecoderRect`] traits from the
//! `image` crate, making djvu-rs a first-class image format usable anywhere
//! image-rs pipelines are used.
//!
//! ## Key public types
//!
//! - [`DjVuDecoder`] — implements `image::ImageDecoder` and `image::ImageDecoderRect`
//!   for a single DjVu page (compatible with `image` 0.25+)
//! - [`ImageCompatError`] — typed errors from this module
//!
//! ## Usage
//!
//! ```no_run
//! use djvu_rs::{DjVuDocument, image_compat::DjVuDecoder};
//! use image::ImageDecoder;
//!
//! let data = std::fs::read("file.djvu").unwrap();
//! let doc = DjVuDocument::parse(&data).unwrap();
//! let page = doc.page(0).unwrap();
//!
//! let decoder = DjVuDecoder::new(&page).unwrap();
//! let (w, h) = decoder.dimensions();
//! let mut buf = vec![0u8; decoder.total_bytes() as usize];
//! decoder.read_image(&mut buf).unwrap();
//! ```

use image::{
    ColorType, ImageDecoder, ImageDecoderRect, ImageResult,
    error::{DecodingError, ImageError, ImageFormatHint},
};

use crate::djvu_document::DjVuPage;
use crate::djvu_render::{RenderError, RenderOptions};

// ---- Error ------------------------------------------------------------------

/// Errors from the image-rs integration layer.
#[derive(Debug, thiserror::Error)]
pub enum ImageCompatError {
    /// The underlying render pipeline failed.
    #[error("render error: {0}")]
    Render(#[from] RenderError),
}

impl From<ImageCompatError> for ImageError {
    fn from(e: ImageCompatError) -> Self {
        ImageError::Decoding(DecodingError::new(
            ImageFormatHint::Name("DjVu".to_string()),
            e,
        ))
    }
}

// ---- DjVuDecoder ------------------------------------------------------------

/// An `image::ImageDecoder` and `image::ImageDecoderRect` for a single DjVu page.
///
/// By default renders at the native page resolution. Use [`DjVuDecoder::with_size`]
/// to override the output dimensions.
pub struct DjVuDecoder<'a> {
    page: &'a DjVuPage,
    width: u32,
    height: u32,
}

impl<'a> DjVuDecoder<'a> {
    /// Construct a decoder from a [`DjVuPage`] reference.
    ///
    /// The output dimensions default to the native page size from the INFO chunk.
    pub fn new(page: &'a DjVuPage) -> Result<Self, ImageCompatError> {
        Ok(Self {
            width: page.width() as u32,
            height: page.height() as u32,
            page,
        })
    }

    /// Override the output dimensions.
    ///
    /// The rendered image will be scaled to `width × height` using bilinear
    /// interpolation via [`RenderOptions`].
    #[must_use]
    pub fn with_size(mut self, width: u32, height: u32) -> Self {
        self.width = width;
        self.height = height;
        self
    }

    /// Render the full page into an RGBA byte buffer.
    fn render_to_vec(&self) -> Result<Vec<u8>, ImageCompatError> {
        let opts = RenderOptions {
            width: self.width,
            height: self.height,
            ..RenderOptions::default()
        };
        let size = (self.width as usize)
            .saturating_mul(self.height as usize)
            .saturating_mul(4);
        let mut buf = vec![0u8; size];
        self.page.render_into(&opts, &mut buf)?;
        Ok(buf)
    }
}

// ---- ImageDecoder impl ------------------------------------------------------

impl<'a> ImageDecoder for DjVuDecoder<'a> {
    fn dimensions(&self) -> (u32, u32) {
        (self.width, self.height)
    }

    fn color_type(&self) -> ColorType {
        ColorType::Rgba8
    }

    fn read_image(self, buf: &mut [u8]) -> ImageResult<()>
    where
        Self: Sized,
    {
        let data = self.render_to_vec().map_err(ImageError::from)?;
        if buf.len() != data.len() {
            return Err(ImageError::Decoding(DecodingError::new(
                ImageFormatHint::Name("DjVu".to_string()),
                format!(
                    "buffer size mismatch: expected {}, got {}",
                    data.len(),
                    buf.len()
                ),
            )));
        }
        buf.copy_from_slice(&data);
        Ok(())
    }

    fn read_image_boxed(self: Box<Self>, buf: &mut [u8]) -> ImageResult<()> {
        (*self).read_image(buf)
    }
}

// ---- ImageDecoderRect impl --------------------------------------------------

impl<'a> ImageDecoderRect for DjVuDecoder<'a> {
    /// Decode a rectangular region of the page.
    ///
    /// DjVu does not natively support partial rendering; this implementation
    /// renders the full page and copies out the requested rectangle.
    /// `row_pitch` is the number of bytes between the start of consecutive
    /// rows in `buf` (must be ≥ `width * bytes_per_pixel`).
    fn read_rect(
        &mut self,
        x: u32,
        y: u32,
        width: u32,
        height: u32,
        buf: &mut [u8],
        row_pitch: usize,
    ) -> ImageResult<()> {
        let bytes_per_pixel = self.color_type().bytes_per_pixel() as usize;
        let full_row_bytes = self.width as usize * bytes_per_pixel;
        let rect_row_bytes = width as usize * bytes_per_pixel;

        // Validate rectangle stays within image bounds.
        let x_end = x.checked_add(width).ok_or_else(|| {
            ImageError::Decoding(DecodingError::new(
                ImageFormatHint::Name("DjVu".to_string()),
                "rectangle x+width overflows u32",
            ))
        })?;
        let y_end = y.checked_add(height).ok_or_else(|| {
            ImageError::Decoding(DecodingError::new(
                ImageFormatHint::Name("DjVu".to_string()),
                "rectangle y+height overflows u32",
            ))
        })?;
        if x_end > self.width || y_end > self.height {
            return Err(ImageError::Decoding(DecodingError::new(
                ImageFormatHint::Name("DjVu".to_string()),
                format!(
                    "rectangle ({x},{y},{width},{height}) out of image bounds ({}×{})",
                    self.width, self.height
                ),
            )));
        }

        let full = self.render_to_vec().map_err(ImageError::from)?;

        for row in 0..height as usize {
            let src_y = y as usize + row;
            let src_start = src_y * full_row_bytes + x as usize * bytes_per_pixel;
            let src_end = src_start + rect_row_bytes;
            let dst_start = row * row_pitch;
            let dst_end = dst_start + rect_row_bytes;

            buf[dst_start..dst_end].copy_from_slice(&full[src_start..src_end]);
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use image::{ColorType, ImageDecoder};

    fn assets_path() -> std::path::PathBuf {
        std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("references/djvujs/library/assets")
    }

    fn load_page(name: &str) -> crate::djvu_document::DjVuDocument {
        let data = std::fs::read(assets_path().join(name))
            .unwrap_or_else(|_| panic!("{name} must exist"));
        crate::djvu_document::DjVuDocument::parse(&data)
            .unwrap_or_else(|e| panic!("parse: {e}"))
    }

    #[test]
    fn dimensions_match_page_size() {
        let doc = load_page("chicken.djvu");
        let page = doc.page(0).unwrap();
        let decoder = DjVuDecoder::new(page).unwrap();
        let (w, h) = decoder.dimensions();
        assert_eq!(w, page.width() as u32);
        assert_eq!(h, page.height() as u32);
    }

    #[test]
    fn color_type_is_rgba8() {
        let doc = load_page("chicken.djvu");
        let page = doc.page(0).unwrap();
        let decoder = DjVuDecoder::new(page).unwrap();
        assert_eq!(decoder.color_type(), ColorType::Rgba8);
    }

    #[test]
    fn total_bytes_equals_w_times_h_times_4() {
        let doc = load_page("chicken.djvu");
        let page = doc.page(0).unwrap();
        let decoder = DjVuDecoder::new(page).unwrap();
        let (w, h) = decoder.dimensions();
        assert_eq!(decoder.total_bytes(), (w as u64) * (h as u64) * 4);
    }

    #[test]
    fn read_image_fills_buffer() {
        let doc = load_page("chicken.djvu");
        let page = doc.page(0).unwrap();
        let decoder = DjVuDecoder::new(page).unwrap();
        let n = decoder.total_bytes() as usize;
        let mut buf = vec![0u8; n];
        decoder.read_image(&mut buf).unwrap();
        // At least some pixels must be non-zero for a real page
        assert!(buf.iter().any(|&b| b != 0), "rendered image must have non-zero pixels");
    }

    #[test]
    fn read_image_wrong_buffer_size_returns_error() {
        let doc = load_page("chicken.djvu");
        let page = doc.page(0).unwrap();
        let decoder = DjVuDecoder::new(page).unwrap();
        let mut buf = vec![0u8; 4]; // far too small
        let result = decoder.read_image(&mut buf);
        assert!(result.is_err(), "wrong buffer size must return error");
    }

    #[test]
    fn with_size_overrides_dimensions() {
        let doc = load_page("chicken.djvu");
        let page = doc.page(0).unwrap();
        let decoder = DjVuDecoder::new(page).unwrap().with_size(64, 48);
        let (w, h) = decoder.dimensions();
        assert_eq!((w, h), (64, 48));
    }

    #[test]
    fn read_rect_full_page_matches_read_image() {
        use image::ImageDecoderRect;
        let doc = load_page("chicken.djvu");
        let page = doc.page(0).unwrap();
        let decoder = DjVuDecoder::new(page).unwrap().with_size(32, 24);
        let (w, h) = decoder.dimensions();
        let n = (w as usize) * (h as usize) * 4;

        let mut full = vec![0u8; n];
        // Use a separate decoder for read_image (consumes self)
        let decoder2 = DjVuDecoder::new(page).unwrap().with_size(32, 24);
        decoder2.read_image(&mut full).unwrap();

        let mut rect_buf = vec![0u8; n];
        let mut decoder3 = DjVuDecoder::new(page).unwrap().with_size(32, 24);
        decoder3.read_rect(0, 0, w, h, &mut rect_buf, w as usize * 4).unwrap();

        assert_eq!(full, rect_buf, "full read_image and read_rect(full page) must match");
    }

    #[test]
    fn read_rect_out_of_bounds_returns_error() {
        use image::ImageDecoderRect;
        let doc = load_page("chicken.djvu");
        let page = doc.page(0).unwrap();
        let mut decoder = DjVuDecoder::new(page).unwrap().with_size(32, 24);
        let mut buf = vec![0u8; 32 * 24 * 4];
        // x + width > image width
        let result = decoder.read_rect(10, 0, 30, 24, &mut buf, 30 * 4);
        assert!(result.is_err(), "out-of-bounds read_rect must return error");
    }

    #[test]
    fn from_image_compat_error_for_image_error() {
        use image::error::ImageError;
        let err = ImageCompatError::Render(crate::djvu_render::RenderError::InvalidDimensions {
            width: 0,
            height: 0,
        });
        let image_err: ImageError = err.into();
        let s = image_err.to_string();
        assert!(s.contains("DjVu"), "ImageError must mention DjVu: {s}");
    }

    #[test]
    fn read_image_boxed_works() {
        let doc = load_page("chicken.djvu");
        let page = doc.page(0).unwrap();
        let decoder = Box::new(DjVuDecoder::new(page).unwrap().with_size(16, 12));
        let n = (16 * 12 * 4) as usize;
        let mut buf = vec![0u8; n];
        decoder.read_image_boxed(&mut buf).unwrap();
        assert!(buf.iter().any(|&b| b != 0));
    }

    #[test]
    fn read_rect_x_plus_width_overflow_returns_error() {
        use image::ImageDecoderRect;
        let doc = load_page("chicken.djvu");
        let page = doc.page(0).unwrap();
        let mut decoder = DjVuDecoder::new(page).unwrap().with_size(32, 24);
        let mut buf = vec![0u8; 4];
        // x = u32::MAX, width = 1 → overflow
        let result = decoder.read_rect(u32::MAX, 0, 1, 1, &mut buf, 4);
        assert!(result.is_err(), "x+width overflow must return error");
    }

    #[test]
    fn read_rect_y_plus_height_overflow_returns_error() {
        use image::ImageDecoderRect;
        let doc = load_page("chicken.djvu");
        let page = doc.page(0).unwrap();
        let mut decoder = DjVuDecoder::new(page).unwrap().with_size(32, 24);
        let mut buf = vec![0u8; 4];
        // y = u32::MAX, height = 1 → overflow
        let result = decoder.read_rect(0, u32::MAX, 1, 1, &mut buf, 4);
        assert!(result.is_err(), "y+height overflow must return error");
    }
}

//! Parser for the DjVu INFO chunk, which contains per-page metadata.
//!
//! INFO chunk layout (from sndjvu.org spec):
//!
//! ```text
//! Offset  Size  Field
//! 0       2     width            big-endian u16
//! 2       2     height           big-endian u16
//! 4       1     minor_version
//! 5       1     major_version
//! 6       2     dpi              little-endian u16
//! 8       1     gamma_byte       actual_gamma = gamma_byte / 10.0
//! 9       1     flags            bits 0-1: rotation, bit 6: orientation
//! ```
//!
//! The minimum INFO chunk size is 10 bytes; some older files may omit the
//! trailing fields.

use crate::error::IffError;

/// Page rotation encoded in INFO flags bits 0–1.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub enum Rotation {
    /// 0° — natural orientation.
    None,
    /// 90° counter-clockwise.
    Ccw90,
    /// 180° rotation.
    Rot180,
    /// 90° clockwise (270° counter-clockwise).
    Cw90,
}

/// Metadata from the INFO chunk of a DjVu page.
#[derive(Debug, Clone, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct PageInfo {
    /// Page width in pixels.
    pub width: u16,
    /// Page height in pixels.
    pub height: u16,
    /// Resolution in dots per inch.
    pub dpi: u16,
    /// Display gamma (e.g. 2.2).
    pub gamma: f32,
    /// Page rotation.
    pub rotation: Rotation,
}

impl PageInfo {
    /// Parse a [`PageInfo`] from the raw bytes of an INFO chunk.
    ///
    /// # Errors
    ///
    /// Returns [`IffError::Truncated`] if the data is shorter than 10 bytes.
    pub fn parse(data: &[u8]) -> Result<Self, IffError> {
        if data.len() < 10 {
            return Err(IffError::Truncated);
        }

        // width and height are big-endian u16
        let width = u16::from_be_bytes(data[0..2].try_into().map_err(|_| IffError::Truncated)?);
        let height = u16::from_be_bytes(data[2..4].try_into().map_err(|_| IffError::Truncated)?);

        // DPI is little-endian u16 at offset 6
        let dpi = u16::from_le_bytes(data[6..8].try_into().map_err(|_| IffError::Truncated)?);

        // Gamma: byte value / 10.0 (e.g. 22 → 2.2)
        let gamma_byte = data[8];
        let gamma = if gamma_byte == 0 {
            2.2_f32 // default gamma when not specified
        } else {
            gamma_byte as f32 / 10.0
        };

        // Flags byte, bits 0–2: rotation per DjVu spec.
        // Real-world DjVu files use three specific flag values:
        //   5 → CW 90°    2 → 180°    6 → CW 270° (= CCW 90°)
        // Other values (including 1, 3) are treated as no rotation,
        // matching DjVuLibre behavior.
        let flags = data[9];
        let rotation = match flags & 0x07 {
            5 => Rotation::Cw90,
            2 => Rotation::Rot180,
            6 => Rotation::Ccw90,
            _ => Rotation::None,
        };

        Ok(PageInfo {
            width,
            height,
            dpi,
            gamma,
            rotation,
        })
    }
}

